insert into public.curriculum_items
  (class_name, subject, subject_key, strand, sub_strand, content_standard_code, content_standard, indicator_code, indicator, exemplar, sort_order)
values
('Basic 5', 'English Language', 'english', 'Oral Language', 'Songs', 'B5.1.1.1', 'Demonstrate understanding of a variety of songs', 'B5.1.1.1.1', 'Explain the central messages in songs', 'Have learners sing some familiar patriotic songs.; Have learners listen to you sing a selected song.; Guide learners to sing lines of the song with appropriate stress and rhythm.; Let them sing individually and in groups.; Using questions discuss the central message of the target song: Who composed this song? What is the song telling us?; Invite individuals to explain the central message(s) of the song.', 10),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Songs', 'B5.1.1.1', 'Demonstrate understanding of a variety of songs', 'B5.1.1.1.2', 'Relate values in songs to real life experiences', 'Have learners sing familiar songs as in the previous lesson.; Lead learners to discuss the song and have them bring out the meaning.; In groups, learners discuss the values in the song, e.g. truthfulness, patience, etc. and relate the values to real life situations.; Have groups share their ideas with the class in the form of presentations.; Write salient responses on the chalkboard.', 20),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Poems', 'B5.1.3.1', 'Appreciate poems and other pieces of literary materials', 'B5.1.3.1.1', 'Respond to poems by discussing their central messages and expressing own opinion', 'Ask learners to recite a poem of their choice with actions.; Choose a poem appropriate for the grade level.; Recite and act out the poem as learners listen attentively to you and observe.; Allow some individual learners to recite as others listen.; Lead learners to recite lines of the poem with correct stress, clapping and tapping out the rhythm.', 30),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Poems', 'B5.1.3.1', 'Appreciate poems and other pieces of literary materials', 'B5.1.3.1.2', 'Relate values in poems to day-to-day life', 'Ask learners to recite some poems already learnt. Write out a new poem on the board. Teach the meaning and pronunciation of the key words in context.; Lead learners to read the poem line by line and discuss with them the meaning of the whole poem.; Recite the poem with pupils line by line, clapping and tapping out the rhythm.; Together with learners identify and discuss some values in the poem, e.g. patience, love, patriotism etc.; Have learners relate the values to real life situations and experiences.', 40),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Poems', 'B5.1.3.1', 'Appreciate poems and other pieces of literary materials', 'B5.1.3.1.3', 'Compose six-line poems', 'Have learners recite a poem of their choice individually and in groups.; Put learners into groups and ask them to write out some lines of the recited poems.; Assign learners to create or write some meaningful lines similar to those in the poem of their choice.; Guide learners to arrange their formulated lines together to compose a poem of six lines.; Have each group recite their poem while others listen.; Ask the class to identify the values in the poems as they listen to recitations.', 50),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Poems', 'B5.1.4.1', 'Respond to stories', 'B5.1.4.1.1', 'Demonstrate understanding of lessons in stories by making relevant comments', 'Tell a story using the appropriate procedure or stages. With examples, guide learners to identify the beginning, middle and ending.; Invite learners to retell story sequentially. Story Element: What are the key details about this story? Who is the main character? What is the setting? What event(s) happened at the beginning of the story? What event(s) happened at the middle of the story? What event(s) happened at the end of the story?; Have learners take turns to comment on the story.', 60),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Poems', 'B5.1.4.1', 'Respond to stories', 'B5.1.4.1.2', 'Tell stories which are parallel to stories heard or read', 'Use an example to explain a parallel poem or story.; Lead the class to write a story parallel to a familiar story.; Present another short story on the board.; Elicit and discuss areas that can be changed or replaced to create a parallel story. Assign groups to write and present stories parallel to that on the board.', 70),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Dramatization and Role Play', 'B5.1.5.1', 'Appreciate pieces of literary materials through dramatisation', 'B5.1.5.1.1', 'Use costume to dramatise or role-play parts/whole of stories', 'Lead learners to select a familiar story for dramatisation.; Ask questions to review the story.; Assign groups to prepare (share roles, select costume and rehearse) and dramatise/role-play the story using improvised lines.; Invite groups to perform for the class to critique their performances.', 80),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Dramatization and Role Play', 'B5.1.5.2', 'Appreciate key issues in stories/sketches', 'B5.1.5.2.1', 'Interpret moral values in plays/stories', 'Select stories or plays recently watched or read by learners.; Use questions to guide learners to identify the moral values (e. g. truthfulness, perseverance, etc.) in the story/play.; Put learners in groups to interpret the moral values identified and share their interpretation with the class.; Have learners discuss how to apply those values to day-to-day living.', 90),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Dramatization and Role Play', 'B5.1.5.2', 'Appreciate key issues in stories/sketches', 'B5.1.5.2.2', 'Develop sketches from stories read or heard', 'Through discussion, guide learners to identify the parts in stories read.; Invite some learners to retell parts of a story read or heard.; Discuss the story with learners.; Use the activity to guide learners in groups to develop a sketch from the story.; Have learners read out their sketches to the class for comments.', 100),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Dramatization and Role Play', 'B5.1.5.2', 'Appreciate key issues in stories/sketches', 'B5.1.5.2.3', 'Analyse the actions of characters in sketches', 'Sing songs that accompany story telling with learners.; Choose familiar stories from learners’ background.; Put learners into groups. Revise the previous activity on writing short sketches. Learners sketch a story told.; Through questions guide learners to identify and analyse characters and their actions in their sketches.', 110),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Customs, Social/Cultural Values and Manners', 'B5.1.6.1', 'Use culturally acceptable language for communication', 'B5.1.6.1.1', 'Describe/talk about names of regions/places in the country as well as personalities in the community, expressing ideas and feelings clearly Note: Items in this indicator should be treated in separate lessons. The procedure below may be useful', 'Discuss some important personalities in the community,; Ask pupils to mention the regions in the country.; In groups, have learners talk about important places in in each region.; Have groups read their findings to the class.; Encourage the class to ask questions for clarification of ideas', 120),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Customs, Social/Cultural Values and Manners', 'B5.1.6.2', 'Demonstrate positive listening and viewing attitudes and behaviour by showing attentiveness and understanding', 'B5.1.6.2.1', 'Maintain appropriate posture and facial expression', 'Discuss with learners the importance of appropriate posture and facial expression in conversation.; Learners in groups choose a theme and engage in conversation maintaining appropriate posture and facial expressions. Learners listen and observe the speaker’s use of these skills and later critique to help them acquire or improve them.', 130),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Customs, Social/Cultural Values and Manners', 'B5.1.6.2', 'Demonstrate positive listening and viewing attitudes and behaviour by showing attentiveness and understanding', 'B5.1.6.2.2', 'Listen and view for the entire duration of a text, speech, presentation, video etc', 'Play an audio video on your phone or laptop and let learners listen carefully. Set a task to guide them to focus on the activity.; Discuss what they saw and heard. Learners in their groups describe what they saw and heard and do a presentation.; Select a real life scenario e.g. head teacher addressing the school after winning the sports competition. Learners in groups organise their speech; elect a representative to read while others listen.', 140),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Customs, Social/Cultural Values and Manners', 'B5.1.6.3', 'Use knowledge of language and communicative skills to participate in conversation CONT’D', 'B5.1.6.3.1', 'Engage in collaborative conversation on topics such as social issues, values and manners with adults', 'Show the video of a talk show or introduce a talk show by drawing on learners background knowledge of such activities on TV.; Identify an interesting topic e.g. “Children should not WhatsApp”. Initiate a conversation using questions. Learners take turns to contribute to the conversation.; Put learners in groups and let them choose a topic for conversation. Go round to ensure learners take turns, use facial expressions appropriately and maintain eye contact when in conversation.; Put learners in groups to identify and discuss social values (e. g. honesty), what they are and behaviours that portray these values.', 150),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Customs, Social/Cultural Values and Manners', 'B5.1.6.3', 'Use knowledge of language and communicative skills to participate in conversation CONT’D', 'B5.1.6.3.2', 'Demonstrate turn taking in conversation in different topics and follow agreed-upon rules for conversation,', 'e.g. listening to others, speaking one at a time.; Through discussion, guide learners to identify some events that happened in the day or recently.; Invite some individual learners to discuss with the class some experiences. e.g. The learner was late and had to help somebody on the way to school.; Have a pair of learners converse on a given topic (e.g. a football match) as others watch.; Learners in pairs then converse, talking about different topics after the example presented.; Guide the use of appropriate vocabulary by showing vocabulary cards and indirectly dropping hints of a correct word.; Encourage learners to take turns in the activity. e.g. What did you just say? Say that again. Can you repeat what you said, sorry, excuse me. Learners demonstrate the use of this in pairs in front of the class.', 160),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Customs, Social/Cultural Values and Manners', 'B5.1.6.3', 'Use knowledge of language and communicative skills to participate in conversation CONT’D', 'B5.1.6.3.3', 'Respond to questions to give further clarification of an opinion', 'Revise the activity on the talk show. Learners give examples of some vocabulary learnt.; Together with learners, choose a topic and initiate a conversation. Encourage learners to ask questions for clarification, and use appropriate expressions.; Put pupils into groups. Have each group choose a theme and initiate a conversation on their theme. Have the others listen and ask questions.; Have the group respond to the questions to give further clarifications', 170),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B5.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B5.1.7.1.1', 'Employ the Think-Aloud strategy to convey meaning from level-appropriate texts', 'Have learners listen to an audio text or a teacher-read text.; Model Think-Aloud strategy to make meaning from the text.; Have learners practise the Think-Aloud strategy to construct meaning.', 180),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B5.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B5.1.7.1.2', 'Make connections with events in drama', 'Have learners listen to an audio drama or watch a video.; Guide learners to identify the sequence of events in the story, i.e. events at the beginning, middle and ending.; Ask relevant questions to guide learners to relate the events in the drama to their lives.', 190),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B5.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B5.1.7.1.3', 'Relate to lessons in stories', 'Assist learners to revise the sequence of a story familiar to them.; Have learners identify the characters in the story and the roles the characters played in the story or text.; Learners again identify the setting of the story.; Learners identify the moral lessons from the story.; Help them discuss and relate the moral lessons to their lives using an example to illustrate that.; Read a short story to learners and in groups, have them relate to the lessons in the story by repeating the above activities.', 200),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B5.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B5.1.7.1.4', 'Use background knowledge to understand and build new knowledge while listening to drama', 'Have learners listen to a drama.; Learners in groups identify, discuss and relate the plot of the drama to a familiar text.; Have learners listen to the drama a second time.; In groups, learners share what they have learnt in the text.', 210),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B5.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B5.1.7.1.5', 'Ask relevant questions to expand comprehension of details of texts', 'Through discussion, learners identify some interesting stories or texts they have heard or read.; Assist learners to talk about the content of the stories/texts after re-telling the story. Encourage learners to ask relevant questions to expand their comprehension of the details of the text.', 220),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B5.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B5.1.7.1.6', 'Distinguish between causes and effects of events in a story', 'Select an appropriate story to be read in class.; Have learners read the story and re-tell it to the class.; Work together with learners to identify the events in the story and link them sequentially by identifying cause and effect.; Learners in their groups choose stories and identify the causes and effects of events. Let learners present their work as the rest listen to them.', 230),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B5.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B5.1.7.1.7', 'Draw conclusions from main ideas, key details and specific examples from texts', 'Revise the lessons on identification of cause and effect using Think-Pair-Share.; Select an interesting story to guide the learners do this exercise.; Build on this activity by working together with learners to identify specific examples to help bring out main ideas and the key details. With this example, guide learners to draw conclusions.', 240),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Asking and Answering Questions/ Question Tags', 'B5.1.8.1', 'Demonstrate understanding in asking and answering questions correctly B5.1.8.2: Identify and use question tags correctly in speech', 'B5.1.8.1.1', 'Use the various forms of “do”, “be”, “have”, appropriately in questions and responses', 'Revise Wh and Yes/No questions by having learners respond to several of such questions.; Use the various forms of “do” to construct sentences as learners listen to you. e. g. Do you like lots of pepper? Does he teach here? Did we sleep there?; Answer each question yourself.; Ask the questions again and have learners give the answer.; In pairs, learners ask questions for their partners to answer.; Repeat the procedure to introduce the various forms of “be” (is, am, are etc.) and “have” (has, have, had).', 250),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Asking and Answering Questions/ Question Tags', 'B5.1.8.2', 'Demonstrate understanding in asking and answering questions correctly B5.1.8.2: Identify and use question tags correctly in speech', 'B5.1.8.2.1', 'Use positive tags, negative tags and auxiliaries in speech', 'Play a recorded dialogue containing positive tags or get two learners to engage in a dialogue prepared by the teacher containing positive tags.; Learners listen and in pairs, use positive tags in dialogues. Do the same with negative tags. Go through the same procedure to get learners to use the tags in speech. (Explain that question tags are short questions that follow statements).; Together with learners, discuss the formation of tags by listening to and practising using them in speech. e.g. The bad boys aren’t in school today, are they? In a Question and Answer Drill, pairs of learners ask and answer questions round the class.', 260),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Giving and Following Commands/ Instructions/Directions and Making and Responding to Requests', 'B5.1.9.1', 'Use verbs in commands, instructions, requests and directions appropriately in speech CONT’D', 'B5.1.9.1.1', 'Give and respond to commands, instructions; give and follow directions with clear landmarks', 'Revise the concept of giving commands and making requests.; In pairs, have learners role-play giving and obeying or following commands/instructions.; Model giving simple directions to places in the school and important places in the community or environment.; Provide situations for learners to practise giving directions. E.g. "A stranger meets you at the school gate. Direct him or her to the chief''s palace, Central Mosque etc.; Learners work in groups to give directions.', 270),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Giving and Following Commands/ Instructions/Directions and Making and Responding to Requests', 'B5.1.9.1', 'Use verbs in commands, instructions, requests and directions appropriately in speech CONT’D', 'B5.1.9.1.2', 'Make and respond to polite requests for help from familiar adults', 'Revise how to make requests by giving examples.; In a discussion, help learners to identify the need to use “please” when making simple requests. Through demonstration, guide learners to make polite requests in the classroom. e.g. i. Please sir/madam, may I go out? ii. Yes, you may.; Invite learners to the front in pairs to dramatise/role-play situations/scenes where they make requests and respond to them. Provide and teach vocabulary and expressions to guide them make requests and respond to them.', 280),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Presentation', 'B5.1.10.1', 'Demonstrate knowledge of spoken grammar and register', 'B5.1.10.1.1', 'Demonstrate awareness of the features of spoken language,', 'e.g. use of discourse markers – well, also, finally; Revise important features of spoken language such as use of contractions and ellipsis.; Help learners to use contractions and ellipsis in speech. E.g.; 1. Contraction: i. Kofi cannot come today. ii. Kofi can’t come today.; 2. Ellipis: A: When will you come? B: Tomorrow', 290),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Presentation', 'B5.1.10.1', 'Demonstrate knowledge of spoken grammar and register', 'B5.1.10.1.2', 'Demonstrate awareness of the differences between spoken and written forms of language,', 'e.g. formal and informal register; Revise some differences between spoken and written forms of language, e.g. simplicity in spoken sentences and complexity of written sentences. e.g. written: I have not gone there. spoken: I haven’t gone there.; Demonstrate simplicity of spoken language by giving short and simple speeches on a topic. E.g. Introduction of a chairman.; Encourage learners to give short and simple speeches on chosen topics, e.g. My Favourite Meal.', 300),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Presentation', 'B5.1.10.1', 'Demonstrate knowledge of spoken grammar and register', 'B5.1.10.1.3', 'Demonstrate awareness of how meaning is conveyed through appropriate pace, stress, tone', '– through reciting poems.; Perform a familiar poem as learners listen and observe.; Have learners discuss the recital with focus on intonation, stress and rhythm.; Perform it again and have the class or groups do same.; Individuals, pairs and groups now choose and perform their favourite poems.; Have the class critique each effort.', 310),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Presentation', 'B5.1.10.2', 'Demonstrate the ability to communicate with accurate pronunciation and appropriate intonation', 'B5.1.10.2.1', 'Speak audibly and coherently, using the appropriate voice qualities (pace, tone etc.)', 'Have learners listen to a conversation or speech in which the speaker speaks fluently and clearly and another audio where the speech is neither clear nor fluent.; Discuss the differences and ask learners to tell the importance of clear speech.; Create situations for learners to engage in dialogue (a pair at a time) or speech delivery.; Encourage them to maintain a good pace and tone.; Invite comments from the class after each delivery.', 320),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Presentation', 'B5.1.10.2', 'Demonstrate the ability to communicate with accurate pronunciation and appropriate intonation', 'B5.1.10.2.2', 'Read aloud clearly, at a good pace and with expression', 'Have learners listen to audio recordings of speeches or listen to news read in English.; Learners listen to the speech in meaningful bits to guide them identify appropriate expressions as well as identify what a good pace is.; Use further samples to show that good speeches are presented with the appropriate expression and at a good pace.; In groups learners pick topics for their speeches. They prepare and deliver in turns. Let them deliver the speeches in about five (5) minutes each.; Have the class discuss the pace and use of appropriate expressions.', 330),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Presentation', 'B5.1.10.3', 'Plan and present information and ideas for a variety of purposes', 'B5.1.10.3.1', 'Present information about personal experiences', 'Model presenting a speech on a topic or have them listen to a recording of someone''s personal experience. Use the example to guide learners to identify the (purpose of and audience for the speech.); Discuss the importance of purpose and audience in speech.; Put learners in groups to plan a parallel speech and present to the class. Each group should select a purpose for and an audience for their speech.', 340),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Presentation', 'B5.1.10.3', 'Plan and present information and ideas for a variety of purposes', 'B5.1.10.3.2', 'Draw on prior knowledge to identify organisational structure of speech', 'Have learners listen to a speech and give the written text to them to read taking note of the features.; Discuss the structure of a model speech with learners: e.g. i. Heading ii. Vocative Address iii. Introduction iv. Body; In groups have pupils write and present a parallel speech. Have the class critique each group’s work based on the discussed structures.', 350),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Presentation', 'B5.1.10.3', 'Plan and present information and ideas for a variety of purposes', 'B5.1.10.3.3', 'Gather and select facts and ideas from one or multiple print and non-print sources, appropriate to the purpose, audience, context and culture', 'Review the organizational structure of the speech with pupils by giving a short speech and asking them to identify the various structures.; Provide sample speeches for discussion to help learners generate ideas for their speeches.; Use the internet to guide the learners to download important speeches.; Together with learners, discuss the organisational structure of the speeches.; Have learners choose and write speeches.', 360),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Presentation', 'B5.1.10.3', 'Plan and present information and ideas for a variety of purposes', 'B5.1.10.3.4', 'Support ideas and points of view by integrating selected visual and audio resources, verbal and non-verbal cues (', 'e.g. gestures, facial expressions); Through discussion, guide learners to select facts and ideas from one or more sources such as print sources and non- print sources (e.g. resource person) appropriate to the purpose, audience, context and culture.; Encourage learners to ask questions for clarity.', 370),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Presentation', 'B5.1.10.3', 'Plan and present information and ideas for a variety of purposes', 'B5.1.10.3.5', 'Use discourse markers to signpost stages in a presentation (', 'e.g. “For the next part”, “For example”, “In summary”); Select a sample written speech and through discussion help learners to identify discourse markers to signpost stages in a presentation. E.g. “Let us look at,” also, “ To sum up,” “Finally”.; Learners write and use the appropriate words in both formal and informal situations.', 380),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Presentation', 'B5.1.10.3', 'Plan and present information and ideas for a variety of purposes', 'B5.1.10.3.6', 'Elaborate on points using concrete examples', 'Through model discussion help learners to elaborate on their points and substantiate them through the use of details, concrete examples, experiences and feelings.; Have learners present their works to the hearing of others.; Encourage the class to make inputs in one another’s work.', 390),
('Basic 5', 'English Language', 'english', 'Oral Language', 'Presentation', 'B5.1.10.3', 'Plan and present information and ideas for a variety of purposes', 'B5.1.10.3.7', 'Speak with confidence before different audiences and maintain appropriate posture', 'Through role play and frequent practice in presentation, build confidence in learners to enable them stand before different audiences.; Let them demonstrate various postures, maintain eye contact and use verbal and non-verbal signs to convey meaning. Let them practice these in pairs and groups.', 400),
('Basic 5', 'English Language', 'english', 'Reading', 'Phonics', 'B5.2.2.1', 'Connect sounds to letters; and blend letters/syllables in order to read and write', 'B5.2.2.1.1', 'Apply common phonic generalisations (', 'e.g. hard and soft “c” and “g”) when reading continuous texts. e.g. “c” as in country and cell “g” as in gain and age; Review the hard form of the sound, e.g. “c” as in cut; “g” as in get.; Introduce the soft form using lots of examples, e.g. “c” as in centre, cent, circle; “g” as in gent, gin, etc.; In groups, encourage learners to come out with words in which the sounds occur.; Have each group read their words to the class and then publish it on the walls of the classroom for learners to go round to read.', 410),
('Basic 5', 'English Language', 'english', 'Reading', 'Phonics', 'B5.2.2.1', 'Connect sounds to letters; and blend letters/syllables in order to read and write', 'B5.2.2.1.2', 'Read two syllable words with suffixes and "r" controlled words (or, er, ar , ur) when reading continuous texts', 'Introduce learners to the “r” controlled words. e.g. or as in lord, ford er as in her, fern, term, herb ar as in arm, car, park ur as in burn, turn, purse; Invite learners to give their examples.; Put learners into groups and assign each group sounds. Using a dictionary and the internet, have members of each group search for words that contain the sound.; Have each group read their words to the class. Get learners to read two syllable words that contain suffixes and “r” controlled words (e.g. return) in sentences.', 420),
('Basic 5', 'English Language', 'english', 'Reading', 'Word Families: Minimal Pairs and Common Digraphs', 'B5.2.3.1', 'Identify minimal pairs and common digraphs', 'B5.2.3.1.1', 'and show the chart containing words. Let learners think-pair-share and select a paragraph with words containing digraphs', 'e.g. – sash, wash; Give examples of minimal pairs, e.g. watch, catch; In groups let learners come up with more examples; Select two paragraphs from the reading passage and let learners identify specific spelling patterns e.g. sh- fish, dish, sash, wash th – both, tooth; Drill learners on pronunciation of words.; Learners read the words containing minimal pairs, e.g. church, search, perch, fetch.; Work together with learners to write simple sentences with the minimal pairs.; Learners in pairs identify more words from reading passages and make a list on a chart. Let each pair read the words.', 430),
('Basic 5', 'English Language', 'english', 'Reading', 'Word Families: Minimal Pairs and Common Digraphs', 'B5.2.3.1', 'Identify minimal pairs and common digraphs', 'B5.2.3.1.2', 'Use words with digraphs to make meaningful sentences', 'Revise the activity in', 440),
('Basic 5', 'English Language', 'english', 'Reading', 'Diphthongs', 'B5.2.4.1', 'Identify and use diphthongs to decode', 'B5.2.4.1.1', 'Use closing diphthongs,', 'e.g. /aƱ/, /eƱ/to make meaningful sentences; Revise the activity on minimal pairs words. Let learners pick partners, think- pair-share. Learners use their rhyming words in meaningful sentences.; Introduce words that contain the target diphthongs, one at a time, by writing examples on the board e.g. /eƱ/ - go, no, boat, load etc. /aƱ/ - how, fowl etc. Note: Do not write the symbols of the sounds; Learners read and identify the common sound in the words. In groups learners make a list of words containing diphthongs and use some in sentences e.g. she says today is pay day.', 450),
('Basic 5', 'English Language', 'english', 'Reading', 'Blends and Consonant Clusters', 'B5.2.5.1', 'Identify and use consonant blends and clusters in reading', 'B5.2.5.1.1', 'Orally produce two-syllable words by blending sounds (phonemes), including consonant blends', 'Learners individually make meaningful sentences with words containing diphthongs. Every correct sentence is recorded for the group the individual belongs to.; Introduce two-syllable words with consonant blends.; Model the pronunciation and have learners say them after you.; Teacher and learners select a reading text to guide the class to identify words containing consonant blends.; List words on the board and drill learners in their pronunciation.; Learners read sentences and pick out the two-syllable words with consonant blends. e.g. dr-hundred, dr-drumstick, bl-problem, nd-handcuff', 460),
('Basic 5', 'English Language', 'english', 'Reading', 'Blends and Consonant Clusters', 'B5.2.5.1', 'Identify and use consonant blends and clusters in reading', 'B5.2.5.1.2', 'Use the spelling-sound correspondences for common consonant digraphs', 'Revise digraphs. Have a simple presentation of digraphs by writing examples of words that begin or end with them on the board.; Have learners read the words and identify the letters at the beginning and the end. e.g. taught , watch, splash, photographs.; Together with learners use the internet to identify words containing specific digraphs.; Learners write examples of words, find their meanings and use them in sentences. E.g. lt- belt, fr- fresh, pl- play', 470),
('Basic 5', 'English Language', 'english', 'Reading', 'Vocabulary', 'B5.2.6.1', 'Understand word meanings and usages', 'B5.2.6.1.1', 'Use level-appropriate content words (nouns, verbs, adjectives and adverbs), and function words (', 'e.g. prepositions) appropriately in spoken and written communication; Explain to learners that function words glue pieces of sentences together into long patterns. In other words they express a grammatical or structural relationship with other words in a sentence.; Examples of function words are determiners, conjunctions, prepositions, auxiliary verbs, modals etc.; Content words are words with specific meanings such as nouns, adjectives, adverbs and main verbs. e.g. The sly brown fox jumped over the lazy dog.; In groups learners identify and work out the meanings of content words in texts read.; Have them use these words in sentences.', 480),
('Basic 5', 'English Language', 'english', 'Reading', 'Vocabulary', 'B5.2.6.1', 'Understand word meanings and usages', 'B5.2.6.1.2', 'Use the following terms: synonym, antonym, prefix, suffix, phrasal verb etc. in spoken and written expressions', 'Choose a text to guide learners identify synonyms, antonyms, idioms or phrasal verbs etc.; Create a scenario where learners can use idioms, antonyms, prefixes, suffixes and phrasal verbs, synonyms, etc. in meaningful sentences in written and spoken languages.', 490),
('Basic 5', 'English Language', 'english', 'Reading', 'Vocabulary', 'B5.2.6.2', 'Build vocabulary B5.2.6.3: Demonstrate a rich vocabulary that supports the development of listening, reading, speaking, writing and presentation skills', 'B5.2.6.2.1', 'Develop a rich vocabulary stock through extensive reading of age-appropriate texts, using the dictionary or online resources to look up meanings of words etc', 'Choose and read an age-appropriate story to the class.; Have learners talk about the story.; Let them identify unfamiliar vocabulary and find their meanings in context.; Have learners use the Build My Vocab App on the internet to help build the most globally used language to help develop their vocabulary.; Guide learners to choose books from the school library or distribute supplementary readers to them.; Introduce a simple vocabulary book made by teacher to guide the learners build their vocabulary.; Read to learners to encourage them read extensively. Encourage individual learners to read their selected story books to the class.', 500),
('Basic 5', 'English Language', 'english', 'Reading', 'Vocabulary', 'B5.2.6.3', 'Build vocabulary B5.2.6.3: Demonstrate a rich vocabulary that supports the development of listening, reading, speaking, writing and presentation skills', 'B5.2.6.3.1', 'Deduce meaning of words from the word class they belong to and how they relate to one another (synonyms and antonyms)', 'Teach meaning of keywords in a text by using them in sentences.; In groups of six have learners bring out the contextual meaning of the words using synonyms and antonyms.; Have learners use these words in their own sentences.; Have them present their work to the class for feedback.; Have learners play vocabulary games, e.g. The Synonym/Antonym Tree game.', 510),
('Basic 5', 'English Language', 'english', 'Reading', 'Vocabulary', 'B5.2.6.4', 'Use words appropriately for purpose, audience, context and culture', 'B5.2.6.4.1', 'Recognise how words are formed through acronyms (WHO) and clipping (telephone', '–phone).; Have learners revise building vocabulary through affixes. e.g. micro – microscope in – insert con – connect re – return; Learners should find meaning to these affixes and write more examples of affixes. Play a game where learners identify affixes in words. The group with the highest number of words is declared the winner.; Introduce acronyms and clipping. e.g.: acronyms – WHO = World Health Organisation clipping – telephone = phone; Put learners into groups and have them research on acronyms and clipping, using dictionaries or online resources, to build more vocabulary.', 520),
('Basic 5', 'English Language', 'english', 'Reading', 'Vocabulary', 'B5.2.6.4', 'Use words appropriately for purpose, audience, context and culture', 'B5.2.6.4.2', 'Recognise the playful use of words in spoken and written language (jokes, riddles, puns etc.)', 'Demonstrate the playful use of words (jokes, riddles etc.); e.g. Riddle, riddle. I am something. I have four legs and a top. People write or eat on me. What am I?; Have learners use appropriate language in jokes, riddles etc.; Make them understand that these are ways in which language could also be used.', 530),
('Basic 5', 'English Language', 'english', 'Reading', 'Vocabulary', 'B5.2.6.4', 'Use words appropriately for purpose, audience, context and culture', 'B5.2.6.4.3', 'Use words suitable for purpose, audience, context and culture in relation to: type of texts (expository/explanatory, persuasive language, argumentative), medium (spoken/written), register (formal/informal) etc', 'Demonstrate the use of the key elements in writing. E.g. purpose, audience, setting, characters etc.; Have learners to role-play a simple story to bring out the importance of these elements and their usage.', 540),
('Basic 5', 'English Language', 'english', 'Reading', 'Comprehension', 'B5.2.7.1', 'Process and comprehend level appropriate texts', 'B5.2.7.1.1', 'Construct meaning from text read', 'Choose different texts for learners to make meaning from using the different strategies they are familiar with: − Use of prior knowledge/experience. − Making predictions − Contextual meaning of vocabulary to connect with the other words to make meaning.', 550),
('Basic 5', 'English Language', 'english', 'Reading', 'Comprehension', 'B5.2.7.1', 'Process and comprehend level appropriate texts', 'B5.2.7.1.2', 'Note and recall main ideas in a sequence', 'Using SQ3R guide learners to present facts and ideas in a sequential order.', 560),
('Basic 5', 'English Language', 'english', 'Reading', 'Comprehension', 'B5.2.7.1', 'Process and comprehend level appropriate texts', 'B5.2.7.1.3', 'Scan texts for details', 'Guide learners to skim and scan texts for details.; Have learners skim/scan a text in a short period/time frame and write down their ideas.; Discuss the answers together as a class.', 570),
('Basic 5', 'English Language', 'english', 'Reading', 'Comprehension', 'B5.2.7.1', 'Process and comprehend level appropriate texts', 'B5.2.7.1.4', 'Read level-appropriate texts silently and closely for comprehension', 'Revise the Before Reading, During Reading and After Reading strategies introduced to learners.; Provide appropriate texts and ensure that the strategies are used.', 580),
('Basic 5', 'English Language', 'english', 'Reading', 'Comprehension', 'B5.2.7.2', 'Apply critical reading, implied meaning, higher order thinking, judgment and evaluation B5.2.7.3: Demonstrate an understanding of the use of words and phrases as used in a text', 'B5.2.7.2.1', 'Respond to a text with simple judgment', 'Use appropriate questions to guide learners read, identify and present points of view in a text.; Learners create a mental image from the text read visualising/ bringing the text to life by engaging the imagination and using all the senses e.g. use questions to guide them do this activity. Can you describe pictures or images you made in your head when you read the text?; Through relevant questions, have learners respond to the text with simple judgment. Learners should present their points in written or oral form.', 590),
('Basic 5', 'English Language', 'english', 'Reading', 'Comprehension', 'B5.2.7.2', 'Apply critical reading, implied meaning, higher order thinking, judgment and evaluation B5.2.7.3: Demonstrate an understanding of the use of words and phrases as used in a text', 'B5.2.7.2.2', 'Relate two or more ideas in a text', 'Through relevant questions, have learners make personal; connections with a text read. e.g. Does the message in this passage remind you of something? Answer: This story reminds me of a holiday I spent with my grandfather.; Have learners relate two or more ideas within the text or from different texts.', 600),
('Basic 5', 'English Language', 'english', 'Reading', 'Comprehension', 'B5.2.7.2', 'Apply critical reading, implied meaning, higher order thinking, judgment and evaluation B5.2.7.3: Demonstrate an understanding of the use of words and phrases as used in a text', 'B5.2.7.2.3', 'Demonstrate awareness of the structure of texts (', 'e.g. introduction, body, conclusion); Guide learners with questions to identify the main parts of a story, e.g. introduction, body and conclusion.; Have learners use connectives to summarise each part of the text and use these to make a full summary.', 610),
('Basic 5', 'English Language', 'english', 'Reading', 'Comprehension', 'B5.2.7.3', 'Apply critical reading, implied meaning, higher order thinking, judgment and evaluation B5.2.7.3: Demonstrate an understanding of the use of words and phrases as used in a text', 'B5.2.7.3.1', 'Use knowledge of prefixes and suffixes to read and interpret unfamiliar words', 'e.g. mis – misunderstanding; Revise affixes briefly and have learners identify them in words.; Have learners use words in their own sentences', 620),
('Basic 5', 'English Language', 'english', 'Reading', 'Silent Reading', 'B5.2.8.1', 'Construct meaning from texts read', 'B5.2.8.1.1', 'Infer meaning from level-appropriate texts', 'Have learners read silently. Let them stop and think about something different from the text. This is to make them know what to do when meaning is disrupted.; Have them read silently for the meaning from the text.', 630),
('Basic 5', 'English Language', 'english', 'Reading', 'Silent Reading', 'B5.2.8.1', 'Construct meaning from texts read', 'B5.2.8.1.2', 'Find the meaning of words as used in context', 'Use examples to show that words have different meanings.; Have a vocabulary lesson to help learners find meaning of words in a text.; Have learners use Think-Pair-Share to discuss their meaning together.', 640),
('Basic 5', 'English Language', 'english', 'Reading', 'Silent Reading', 'B5.2.8.1', 'Construct meaning from texts read', 'B5.2.8.1.3', 'Answer questions based on the passage read', 'Learners pose and answer questions that clarify meaning and promote deeper understanding of a text.; Questions can be generated by the learner, a peer or an adult. E.g. i. Why did the character do nothing? ii. How did it make them feel?', 650),
('Basic 5', 'English Language', 'english', 'Reading', 'Fluency', 'B5.2.9.1', 'Read fluently to enhance comprehension', 'B5.2.9.1.1', 'Read grade-level texts with good speed and accuracy', 'Use the three-stage approach to a comprehension lesson and have learners prepare and read the text with purpose and understanding.; Use different strategies to assist learners to come up with meaning of a text ,e.g. The Herringbone, KWL etc.', 660),
('Basic 5', 'English Language', 'english', 'Reading', 'Fluency', 'B5.2.9.1', 'Read fluently to enhance comprehension', 'B5.2.9.1.2', 'Use context to confirm or self-correction strategies to confirm understanding of level-appropriate texts', 'Have learners read the grade appropriate texts paying attention to punctuation marks, words, sentences and paragraphs.; Provide questions that will guide learners in understanding the passage, e.g., What word connects paragraphs one and two?; Learners use correction strategy to help them make meaning from the text as they read.', 670),
('Basic 5', 'English Language', 'english', 'Reading', 'Summarising', 'B5.2.10.1', 'Read and summarise passages read', 'B5.2.10.1.1', 'Summarise level-appropriate texts/passages orally', 'Learners identify the most important ideas in texts/passages read and restate them in their own words. E.g. i. Can you retell the story? ii. Who are the main characters? iii. What is the setting? iv. What are the main events? (use herringbone or story map as strategies)', 680),
('Basic 5', 'English Language', 'english', 'Reading', 'Summarising', 'B5.2.10.1', 'Read and summarise passages read', 'B5.2.10.1.2', 'Write a short summary of a level-appropriate text/passage read', 'Have learners work in groups to write a summary of a text/passage read taking note of the main ideas.; Let learners present their write-up for discussion and feedback from the class and teacher.', 690),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Nouns', 'B5.3.1.1', 'Apply knowledge of different types of nouns in communication', 'B5.3.1.1.1', 'Identify and use nouns or noun phrases to refer to quantities or units', 'Revise nouns briefly.; Introduce quantities and units in context. e.g.: − Please, give me a piece of paper. − I have a pair of trousers.; Have learners identify more examples of these in text and use them in sentences.; Learners make up their own noun phrases and use them in sentences.', 700),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Nouns', 'B5.3.1.1', 'Apply knowledge of different types of nouns in communication', 'B5.3.1.1.2', 'Identify and use: − proper nouns - refer to festivals; − Count/non-count − Singular − Plural (regular, irregular) − plural without plural marker Proper nouns', 'Introduce the concept in context. E.g. Christmas is coming. The people of Ga celebrate Homowo. - In pairs have learners give more examples of festivals and write them as proper nouns.', 710),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Nouns', 'B5.3.1.1', 'Apply knowledge of different types of nouns in communication', 'B5.3.1.1.3', 'Identify and use collective nouns to refer to a group of objects and people', 'Teach collective nouns in context.; Introduce a text that contains examples of collective nouns. E.g. such as audience, congregation, a flock of sheep, a troop of monkeys.; Have learners discuss the meaning of these words in context.; Put them into groups to provide more examples of collective nouns and use these nouns in sentences.; Let the groups present their work to the class for feedback.', 720),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Nouns', 'B5.3.1.1', 'Apply knowledge of different types of nouns in communication', 'B5.3.1.1.4', 'Identify and use abstract nouns to refer to concepts and ideas', 'Revise concrete nouns.; Introduce abstract nouns as nouns that cannot be touched, seen or felt. They include ghost, beauty, holiness, air, etc.; Provide a passage with concrete and abstract nouns and let learners identify each category.; Have learners use given concrete and abstract nouns in sentences.', 730),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Determiners', 'B5.3.2.1', 'Apply knowledge of different types of determiners in communication', 'B5.3.2.1.1', 'Identify and use indefinite and definite articles “a” and “an” to refer to a person, animal, event, time or objects in general Note: Teacher should use level-appropriate vocabulary to teach the articles', 'Provide an appropriate text containing abstract, concrete nouns.; Revise the lesson on nouns. Use the same text to introduce definite, indefinites and zero articles. Guide learners with examples to list the articles in the passage.; Help learners to form sentences using the articles.', 740),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Determiners', 'B5.3.2.1', 'Apply knowledge of different types of determiners in communication', 'B5.3.2.1.2', 'Identify and use quantifiers to show qualities: − ordinal first, second etc.) − a few/a little etc. − both each/every − another, other − fewer, less, etc', 'Introduce other types of determiners like each, both, and all.; Let learners read the sentences containing these determiners and explain the sentences.; Provide a text and let learners identify the determiners in a group activity.; Provide a context containing quantifiers. With examples help learners to identify them. e.g. i. Numerals (cardinals – one, two, three); ii. Ordinals (first, second, third); iii. Some few/little etc; iv. No/both, all, each/every.; Help learners to use the quantifiers in sentences.', 750),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Determiners', 'B5.3.2.1', 'Apply knowledge of different types of determiners in communication', 'B5.3.2.1.3', 'Identify and use possessive pronouns to show possession', 'Provide an interesting story abundant in possessives, e.g. mine, yours, his. E.g., This is mine.; Let learners use possessives like mine, yours, his, hers, theirs in sentences. E.g., This story is mine.', 760),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Determiners', 'B5.3.2.1', 'Apply knowledge of different types of determiners in communication', 'B5.3.2.1.4', 'Identify and use demonstratives', '– this/that, these/those people; Have learners identify demonstrations like this/that, these/those in context.; Guide learners with examples to write down the demonstratives.; Have learners use them in sentences. E.g. i. This is for John. ii. That is his plan.', 770),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Determiners', 'B5.3.2.1', 'Apply knowledge of different types of determiners in communication', 'B5.3.2.1.5', 'Identify and use interrogative determiners', 'e.g. which, whose – to find out which person something belongs to; Choose a text that illustrates interrogatives. With an example from the text, guide learners to identify the other interrogatives in the passage.; Create a scenario for them to use the demonstratives appropriately in sentences.', 780),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Pronouns', 'B5.3.3.1', 'Apply knowledge of different types of pronouns in communication', 'B5.3.3.1.1', 'Identify and use indefinite pronouns', 'e.g. someone, anyone, everything etc. Possessive pronouns to show possession, e.g. mine, ours etc.; Introduce indefinite pronouns with examples in sentences.; Discuss the indefinite pronouns with learners.; Provide a passage and group learners to identify indefinite pronouns, and use the pronouns identified in sentences.; Repeat the procedure to teach possessive pronouns.', 790),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Adjectives', 'B5.3.4.1', 'Apply the knowledge of adjectives in communication', 'B5.3.4.1.1', 'Use comparatives forms of regular and irregular adjectives to make comparisons: − Regular', 'e.g. shorter − Irregular: better Note: The teacher should use level-appropriate vocabulary to introduce these concepts.; Revise the formation of the comparative adjective using er and the superlative using est .e.g. fat, fatter, fattest.; Introduce learners to formation of comparison for irregular adjectives.; Let them form the comparative forms for irregular adjectives. e.g. good better Bad worse; Introduce drills to give learners practice in their usage.', 800),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Verbs', 'B5.3.5.1', 'Apply the knowledge of verbs in communication', 'B5.3.5.1.1', 'Use different types of verbs in sentences: − Main verb − Helping verb (primary auxiliary and modal auxiliary', 'Revise verbs using context.; Let learners identify main verbs in sentences. E.g. The boy has bought a new football.; Provide a text and guide learners to identify auxiliary (Primary and Modal) verbs. E.g. is, was, have, has, had, etc.; Create situations and introduce drills for learners to have practice using them.', 810),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Verbs', 'B5.3.5.1', 'Apply the knowledge of verbs in communication', 'B5.3.5.1.2', 'Use appropriate subject-verb agreement', 'Review subjects and verbs in simple sentences.; Use examples to introduce and explain subject-verb agreement.; Present sentences with missing subjects and others without verbs for learners to complete.; Introduce drills e.g. a completion drill to give further practice.', 820),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Verbs', 'B5.3.5.1', 'Apply the knowledge of verbs in communication', 'B5.3.5.1.3', 'Use the simple present form of verbs to express: − Needs/preferences − Thoughts and ideas', 'Revise the simple present form of verbs: − For habitual actions; − For timeless and universal statements; − For facts which may change or hold true indefinitely; − For instantaneous present; − For scheduled future actions.; Introduce the simple present form of verbs in sentences to express needs/preferences, and thoughts/ideas. express needs/preferences − I need new clothes. − I like playing football more than volleyball. thoughts/ideas − I think you are right. − Introduce these appropriately, one at a time and give practice.', 830),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Verbs', 'B5.3.5.1', 'Apply the knowledge of verbs in communication', 'B5.3.5.1.4', 'Use the simple past form of verbs to express past needs, interest and feeling', 'Review the simple present form of verbs by asking learners to use them in sentences to express needs/preferences, and thoughts/ideas.; Review the simple past form of verbs by using them to indicate: − Completed actions or events − Regular actions in the past; Introduce the use of the simple past form of verbs in sentences to express needs, interest and feelings. E.g. Yesterday, I needed some money. I felt his absence badly. I was interested in winning the competition last year.; Introduce these in turns and provide activities for practice.', 840),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Verbs', 'B5.3.5.1', 'Apply the knowledge of verbs in communication', 'B5.3.5.1.5', 'Use irregular form of the simple past tense of verbs,', 'e.g. Irregular – build-built; Revise regular verbs in simple past forms; Introduce the simple past forms of irregular verb in context.; In groups, have learners come out with more simple past forms of irregular verbs.; Let groups read their verbs to the class.; Have learners use the verbs (past forms) in sentences', 850),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Verbs', 'B5.3.5.1', 'Apply the knowledge of verbs in communication', 'B5.3.5.1.6', 'Use the past continuous form of verbs to talk about actions/events that were going on when a second action/event took place', 'Introduce the concept by reviewing the present continuous form of verbs.; Use the concept in context and have learners identify the time of the actions.; Have learners construct similar sentences.; Explain that the past continuous form of verbs is used to talk about actions/events that were going on when a second action/event took place.; In pairs let learners write sentences using the past continuous form of verbs.', 860),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Verbs', 'B5.3.5.1', 'Apply the knowledge of verbs in communication', 'B5.3.5.1.7', 'Use the imperative forms of verbs to give instructions and directions', 'e.g. Switch on the light. Turn right.; Revise commands and requests.; Invite pairs of learners to demonstrate giving instructions and directions.; Create situations for learners to have practice.', 870),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Adverbs', 'B5.3.6.1', 'Apply the knowledge of different types of adverbs in communication', 'B5.3.6.1.1', 'Use adverbs to express manner', 'Revise verbs and adverbs of place and time.; Provide a passage with adverbs of manner.; Have learners identify the adverbs and their functions – modifying verbs. E.g. Mercy ate slowly.; Pair up learners to write short paragraphs using adverbs of manner.; Have pairs present their work to the class for feedback.', 880),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Idiomatic Expressions', 'B5.3.7.1', 'Understand and use idiomatic expressions appropriately in speech and in writing', 'B5.3.7.1.1', 'Identify, explain and use idiomatic expressions correctly', 'Revise idiomatic expressions such as: i. Take after (to resemble) ii. To pull down(to destroy the reputation of someone); Provide a number of idiomatic expressions and discuss their meaning (in context) with learners.; Help learners to interpret given idiomatic expressions in contexts. E.g. i. Kofi takes after his father. ii. They pulled down the Mr. Badu.; Have learners use idiomatic expressions in their own sentences.', 890),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Conjunctions', 'B5.3.8.1', 'Apply the knowledge of conjunctions in speech and in writing', 'B5.3.8.1.1', 'Identify and use simple conjunctions-because, since, so, although', '– to − give reasons, − link contrasting ideas − show results; Revise simple conjunctions. Provide simple sentences and let learners join them using and, or/nor, but.; Introduce because, since, so, although in context. e.g.: I''m late because I missed the bus. Although Afi is has eye problems, she doesn''t wear glasses. He eats well, so he is healthy.; Guide learners to discover the functions of these conjunctions.; Have them practise using these conjunctions in their own sentences.; Provide a passage and have learners identify the conjunctions in the passage.; Let learners form pairs of simple sentences and join them with the conjunctions identified.', 900),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Modals', 'B5.3.9.1', 'Apply the knowledge of modals in speech and in writing', 'B5.3.9.1.1', 'Use modals to express a variety of meanings: − Can: conveys ability: I can drive − May: asks for permission, expresses politeness, possibility: May I go out? − Must: obligation or compulsion, necessity − Shall/will: prediction, intention, determination etc. − Could: tentativeness, politeness − Would: politeness − Might: possibility − Should: obligation − Used to: for past activity/event − Have to/ought to/need to: for obligation', 'Introduce these (one or two at a time) in context.; Use situations and drills to give learners ample practice.', 910),
('Basic 5', 'English Language', 'english', 'Grammar and Usage at Word and Phrase Levels', 'Prepositions', 'B5.3.10.1', 'Apply the knowledge of prepositions in oral and written communication', 'B5.3.10.1.1', 'Use prepositions to convey a variety of meanings: − Position,', 'e.g. by − Direction, e.g. towards − Time, e.g. at − Purpose, e.g. for − Possession, e.g. for − Comparison, e.g. taller than − Support or opposition, e.g. for you, against you; Provide a text and guide learners with examples to identify prepositions used to show different meanings.; Let learners construct sentences to convey the following meanings using appropriate prepositions. i. Position – She is standing by the car. ii. Direction – They went towards the East. iii. Time – He left at dawn. iv. Purpose – I bought this hoe for weeding my garden. v. Possession – The shirt is for Kofi. vi. Comparison – She is taller than her brother. vii. Support or opposition – My views are against his plans.', 920),
('Basic 5', 'English Language', 'english', 'Writing', 'Penmanship and Handwriting', 'B5.4.2.1', 'Copy and rewrite sentences correctly', 'B5.4.2.1.1', 'Copy sentences clearly in joint script maintaining legible handwriting', 'Select sentences from texts learners have read and write them on the board, using joint script. e.g.; Have learners read out the sentence. (in pairs, small groups, large groups); Have learners copy the sentences into their exercise books.; Go round to support struggling learners.', 930),
('Basic 5', 'English Language', 'english', 'Writing', 'Penmanship and Handwriting', 'B5.4.2.1', 'Copy and rewrite sentences correctly', 'B5.4.2.1.2', 'Write compound sentences clearly and correctly', 'Review simple sentences by asking learners to construct them using given verbs.; Construct compound sentences and discuss their structure with learners (they are sentences that have at least two subject and predicates joined by a coordinating conjunction).; Give out texts to small groups of learners to search for compound sentences.; Have the groups write them into their exercise books.; Have individual learners write parallel simple sentences (They should follow the structure of the sentences identified by the groups.', 940),
('Basic 5', 'English Language', 'english', 'Writing', 'Paragraph Development', 'B5.4.3.1', 'Develop, organise and express ideas cohesively in writing and representing for a variety of purposes, audience and context', 'B5.4.3.1.1', 'Choose appropriate ways and modes of writing for a variety of purposes, audiences and contexts and organise facts, ideas and/or points of view in a way appropriate to the mode of delivery, using appropriate text features', 'Work with learners to select sample texts from a variety of models of writing from learners’ readers and teacher’s resources e.g. newspapers, magazines etc. You may take learners to the library for this exercise. Examples of modes of writing. i. Process ii. Narration iii. Description iv. Comparison v. Problem solution vi. Classification vii. Argument Note: Refer to B4 Strand 4, Sub strand 2, Indicators 1 – 3 for explanation of the modes of writing.; Put learners into small groups and assign each group a mode of writing. Note: Present one mode of writing at a time and in different lessons.; Have learners study the sample text.; Guide them through appropriate questions to identify the: i. Mode of writing/types of essay ii. Purpose iii. Audience', 950),
('Basic 5', 'English Language', 'english', 'Writing', 'Paragraph Development', 'B5.4.3.1', 'Develop, organise and express ideas cohesively in writing and representing for a variety of purposes, audience and context', 'B5.4.3.1.2', ') • By way of revision, have learners identify the main idea and supporting ideas', 'Display a Model Paragraph, e.g. The children of Boti go to great lengths to seek the power of education and reading. For example, they build their own school at the beginning of the year! To do this, they use mud to make bricks to build the walls and desks. They use grass and saplings and make a roof. Also, the children of Boti work very hard studying during the school year. Every day they learn something new. Finally, at the end of the year, their minds become fat with knowledge. This is how the children of Boti work hard to seek the power of education and reading.; Have learners read it (or read it to them). Have them do Think- Pair-Share and answer the questions: i. What is this paragraph about? ii. How do you know?; Guide learners towards the idea that the main idea of the paragraph is revealed in the first sentence. Underline the first sentence of the paragraph and write “Topic Sentence” in the margin next to it.', 960),
('Basic 5', 'English Language', 'english', 'Writing', 'Paragraph Development', 'B5.4.3.1', 'Develop, organise and express ideas cohesively in writing and representing for a variety of purposes, audience and context', 'B5.4.3.1.3', 'Elaborate on, explain and or justify the main ideas of a paragraph by providing explanations and examples', 'Display a model paragraph preferably the one above (Refer to', 970),
('Basic 5', 'English Language', 'english', 'Writing', 'Paragraph Development', 'B5.4.3.1', 'Develop, organise and express ideas cohesively in writing and representing for a variety of purposes, audience and context', 'B5.4.3.1.4', 'Use cohesive devices', '– pronouns, repetition of vocabulary or grammatical structures to link ideas in a paragraph, e.g. use connectors to link similar ideas, give reasons and add information; Display a sample paragraph.; Underline the cohesive devices/transitional words.; Have learners read the paragraph and discuss with their peers what the underlined words are doing in the paragraph.; Lead them in a general discussion on what the underlined words are and their role in the paragraph.; Provide a paragraph and leave out the cohesive devices. Have learners complete the paragraph with appropriate transitional words.', 980),
('Basic 5', 'English Language', 'english', 'Writing', 'Writing as a Process', 'B5.4.9.1', 'Apply the skills and strategies for idea generation, selection, development, organisation and revision in writing B5.4.9.2: Develop and express ideas coherently and cohesively in writing', 'B5.4.9.1.1', 'Select a topic of choice on issues in their community, brainstorm and organise ideas before writing', 'Scaffold the writing process. i. Pre-writing; Have learners select and discuss topics of interest on issues in their community with their partners.; Have learners use strategies such as brainstorming and mind map to generate as many ideas as possible about the topics.; Have them organise the ideas into a writing plan using an outline, a chart or appropriate graphic organiser. e.g. line diagram Poor sanitation What is poor sanitation causes/effects solution', 990),
('Basic 5', 'English Language', 'english', 'Writing', 'Writing as a Process', 'B5.4.9.2', 'Apply the skills and strategies for idea generation, selection, development, organisation and revision in writing B5.4.9.2: Develop and express ideas coherently and cohesively in writing', 'B5.4.9.2.1', 'Develop ideas into a two-paragraph draft without considering the writing conventions, using appropriate linking words within and across paragraphs to aid cohesion and avoid ambiguity,', 'e.g. firstly, then, after; Put learners into groups to develop their ideas in', 1000),
('Basic 5', 'English Language', 'english', 'Writing', 'Writing as a Process', 'B5.4.9.3', 'Apply strategies for improving drafts for publishing', 'B5.4.9.3.1', 'Review, and revise the draft by proposing grammar for improvement', 'Have learners review their first draft by reading it slowly and critically several times to identify words/expressions that need to be cancelled.; Guide learners with the questions below: i. Are your ideas in order and easy to understand? ii. Are all the sentences talking about the main idea of the paragraph? iii. Are all the paragraphs talking about the topic?; Have learners read their partners’ draft and offer suggestions.; Encourage learners to feel free to make as many changes as possible to improve their drafts.; Have learners make a clean draft for publishing.', 1010),
('Basic 5', 'English Language', 'english', 'Writing', 'Writing as a Process', 'B5.4.9.3', 'Apply strategies for improving drafts for publishing', 'B5.4.9.3.3', 'Display writing piece for peers to read and publish it in the class magazine', 'Have learners share their writing with their peers classmates and families.; Encourage learners to copy neatly their writing and submit them for publication in the class magazine, school magazine or notice board, The Junior Graphic', 1020),
('Basic 5', 'English Language', 'english', 'Writing', 'Narrative Writing', 'B5.4.10.1', 'Narrate situations, express feelings and convey point of view about the world/ or fictional world', 'B5.4.10.1.1', 'Create settings, characters and at least one plot in a narrative text, using appropriate linking words within and across paragraphs to aid cohesion, and using simple literary devices,', 'e.g. direct speech; Revise the stages of the writing process with learners. E.g. prewriting, writing, revising, editing and publishing.; Guide learners through the process to write about real or imagined experiences or events. E.g. personal narrative; Discuss personal narrative with learners: Note: A personal narrative is a true story told from the writer’s point of view. It is the retelling of an event or experience that has affected the writer’s life. The story should be told naturally to allow readers to experience the event(s) for themselves.', 1030),
('Basic 5', 'English Language', 'english', 'Writing', 'Creative/ Free Writing', 'B5.4.11.1', 'Create texts', 'B5.4.11.1.1', 'Write freely on topics of choice on issues in the community', 'Revise the stages of the writing process; Have learners follow the writing process to create their own pieces on a given topic.; Learners present their work for editing.; Have pupils publish their works on the notice board.', 1040),
('Basic 5', 'English Language', 'english', 'Writing', 'Creative/ Free Writing', 'B5.4.11.1', 'Create texts', 'B5.4.11.1.2', 'Write poems and imaginative narrative stories using knowledge of features of poems and imaginative texts', 'Discuss elements of narrative stories with learners. − Title − Characters − Setting − Plot/story line − Conflict dialogue etc. Note: Stories have people (characters) who face a problem (conflict) in a particular place and time (setting). They show what people do (action) and say (dialogue) to resolve the problem.; Guide learners through the writing process to write their stories.; Put pupils into small groups to plan their writing. − Create characters − Create conflict − Establish a setting − Plan action and dialogue', 1050),
('Basic 5', 'English Language', 'english', 'Writing', 'Descriptive Writing', 'B5.4.12.1', 'Demonstrate knowledge of descriptive words/expressions in writing', 'B5.4.12.1.1', 'Use descriptive words/expressions/sound devices/ figurative language to describe places, personal experiences and events', 'Revise descriptive writing with learners.; Talk about sensory details that allow a reader to visualise a person, a place, a thing or an idea.; Guide learners through the stages of writing.; Write to describe events/situations/places of their choice and personal experiences. Focus on the use of: − Descriptive (adjectives) − Figurative language e.g. simile – metaphor − Sensory details (sensory details that are experience through the senses: sight, smell, touch, taste', 1060),
('Basic 5', 'English Language', 'english', 'Writing', 'Persuasive/Argumentative Writing', 'B5.4.13.1', 'Support an opinion in writing B5.4.13.2: Write arguments to support claims with clear reasons and relevant evidence', 'B5.4.13.1.1', 'Write explanations to support opinions', 'Present a motion to learners. E.g. A teacher is more important than a doctor.; Discuss the meaning and implication of the motion with pupils and invite them to take a stand either for or against the motion.; Put learners into two groups: for the motion and against the motion to write down what they think about it.; Groups read out their opinions to the class for discussion.', 1070),
('Basic 5', 'English Language', 'english', 'Writing', 'Persuasive/Argumentative Writing', 'B5.4.13.2', 'Write arguments to support claims with clear reasons and relevant evidence CONT’D', 'B5.4.13.2.1', 'Introduce claims and support them with clear reasons and evidence using credible sources', 'Working in groups (as in B5.7.1.1), learners provide reasons for the opinions they hold on a topic.; Guide groups to provide evidence for the opinions they hold.; Have groups present their work for discussions.', 1080),
('Basic 5', 'English Language', 'english', 'Writing', 'Persuasive/Argumentative Writing', 'B5.4.13.2', 'Write arguments to support claims with clear reasons and relevant evidence CONT’D', 'B5.4.13.2.2', 'Use words, phrases, and clauses to clarify the relationships between claim(s) and reasons', 'Lead learners to discuss appropriate language for arguments e. g. use of adjectives in their various forms.; You may read out models of argumentative essays to guide learners.', 1090),
('Basic 5', 'English Language', 'english', 'Writing', 'Persuasive/Argumentative Writing', 'B5.4.13.2', 'Write arguments to support claims with clear reasons and relevant evidence CONT’D', 'B5.4.13.2.3', 'Establish and maintain a formal style', 'Using models, discuss the basic structure of an argumentative piece: − Introduction. − Reasons for the stand taken. − Conclusion.; Have groups present full compositions using this structure for class discussions and feedback.', 1100),
('Basic 5', 'English Language', 'english', 'Writing', 'Persuasive/Argumentative Writing', 'B5.4.13.2', 'Write arguments to support claims with clear reasons and relevant evidence CONT’D', 'B5.4.13.2.4', 'Provide a concluding statement that follows from the arguments presented', 'Revise persuasive writing.; Have them go through the writing process to present/state an opinion, explain and justify it so as to persuade the reader to accept their opinion or point of view.; Teach the features of a debate.; Guide learners to select a controversial or debatable topic. Divide the class into two to prepare using the writing process as a guide, and debate on the topic.', 1110),
('Basic 5', 'English Language', 'english', 'Writing', 'Informative/Expository Writing', 'B5.4.14.1', 'Write informative/ expository essays B5.4.14.2: Write the event of the day', 'B5.4.14.1.1', 'Write sentences to describe a process of doing something', 'Use pictures showing the stages of how some dishes are prepared.; Learners in groups observe the picture sequences and write words that give information on the activity.; Each group presents its work for discussion.; Let learners in groups choose a domestic activity they would want to give information on. (They should be able to compose expository pieces of between 90 and 120 words).', 1120),
('Basic 5', 'English Language', 'english', 'Writing', 'Informative/Expository Writing', 'B5.4.14.2', 'Write informative/ expository essays B5.4.14.2: Write the event of the day', 'B5.4.14.2.1', 'Write about incidence or events of the day (', 'e.g. any event witnessed on their way to school) and make radio/TV presentations; Let learners watch TV news at home and write their own news from the pictures they see.; Put learners into groups. Let them brainstorm and write about events of the day. Each group chooses an interesting event and writes the news to broadcast to the class. Let each group choose one person to present the news.; Have learners publish their works on the internet.; Help learners to organise a radio or talk show', 1130),
('Basic 5', 'English Language', 'english', 'Writing', 'Letter Writing', 'B5.4.15.1', 'Write informal letters on given topics', 'B5.4.15.1.1', 'Write to friends about events using appropriate letter formats', 'In groups learners are given samples of friendly letters.; Let them brainstorm and write the important features of the letter and other special things they identify in the letters.; Learners present their information to the whole class to guide the class to learn about such letters.; Guide learners in their groups to choose an imaginary friend they want to write to.; Learners brainstorm and write down ideas on what they would want to include in their letters.; Guide them to write their letters and let them edit their work.; Learners exchange their product with other groups to edit.; Learners read their letters to others.', 1140),
('Basic 5', 'English Language', 'english', 'Using Writing Conventions/grammar Usage', 'Using Capitalisation', 'B5.5.1.1', 'Use capital letters to start the first words in a direct speech', 'B5.5.1.1.1', 'Follow appropriate mechanical convention', 'Ask individual learners to write a formal letter each on a given topic paying attention to correct use of capital letters, the full stop, comma, question mark, exclamation mark, quotation mark, apostrophe, hyphen etc.', 1150),
('Basic 5', 'English Language', 'english', 'Using Writing Conventions/grammar Usage', 'Using Capitalisation', 'B5.5.1.1', 'Use capital letters to start the first words in a direct speech', 'B5.5.1.1.2', 'Writing of lower case and capital letters', 'Guide learners to write about their friends by reading a sample essay on the topic to them.; Guide learners to write one paragraph about their friends after listening to the teacher read a sample essay on the topic to them.; Learners in pairs plan their writing.; Let individuals write about their friends. Learners exchange their work with their partners and guide them to edit.; Ask learners to begin their editing by looking at capital letters e.g. Words that need to start with capital letters such as proper names and letters beginning sentences.; Learners go round to help colleagues who have challenges.; Let learners read some of the finished work in class.', 1160),
('Basic 5', 'English Language', 'english', 'Using Writing Conventions/grammar Usage', 'Using Punctuation', 'B5.5.2.1', 'Show understanding of how punctuations are used appropriately in writing', 'B5.5.2.1.1', 'Use punctuations: - (the comma) to write an address; - (the apostrophe) in contraction', 'Revise the use of the comma before and after "Yes" and "No" in sentences; after addressing a person, e.g. Kofi, can you help me?; Introduce the use of the comma to write an address, and the apostrophe in contraction in context. Provide sample sentences/texts for learners to identify the target punctuations. Introduce one punctuation at a time e.g. I live at Adu Street, Adukrom. They can''t do the work.; Have learners practise using the comma to write an address, and the apostrophe in contraction. Give pairs of learners unpunctuated sentences/texts to punctuate.', 1170),
('Basic 5', 'English Language', 'english', 'Using Writing Conventions/grammar Usage', 'Naming Words/Nouns', 'B5.5.3.1', 'Apply knowledge of different types of nouns in communication', 'B5.5.3.1.1', 'Identify and use nouns or noun phrases to refer to quantities or units', 'Introduce quantities and units in context. E.g. − Please, give me a piece of paper. I have a pair of trousers', 1180),
('Basic 5', 'English Language', 'english', 'Using Writing Conventions/grammar Usage', 'Naming Words/Nouns', 'B5.5.3.1', 'Apply knowledge of different types of nouns in communication', 'B5.5.3.1.2', 'Identify and use proper nouns to refer to festivals; common nouns: − Count/non-count − Singular − Plural (regular, irregular) − plural without plural marker Proper nouns', 'Introduce the concept in context. e.g. Christmas is coming. The people of Ga celebrate Homowo. Count and non-count nouns.; Revise the concept of proper nouns and common nouns giving and eliciting several examples. (Proper nouns refer to particular nouns such as names of people, places, mountains, etc.); Provide a text and let learners identify count and non-count nouns.; Have groups use the nouns identified in simple sentences.; Invite groups to present their work.', 1190),
('Basic 5', 'English Language', 'english', 'Using Writing Conventions/grammar Usage', 'Naming Words/Nouns', 'B5.5.3.1', 'Apply knowledge of different types of nouns in communication', 'B5.5.3.1.3', 'Identify and use collective nouns to refer to a group of objects and people', 'Teach collective nouns in context.; Introduce a text that contains examples of collective nouns E.g. such as audience, congregation, a flock of sheep, a troop of monkeys,; Have learners discuss the meaning of these words in context.; Put them into groups to provide more examples of collective nouns and use these nouns in sentences.; Let the groups present their work to the class for feedback.', 1200),
('Basic 5', 'English Language', 'english', 'Using Writing Conventions/grammar Usage', 'Naming Words/Nouns', 'B5.5.3.1', 'Apply knowledge of different types of nouns in communication', 'B5.5.3.1.4', 'Identify and use abstract nouns to refer to concepts and ideas', 'Revise concrete nouns. Introduce abstract nouns as nouns or names of things that cannot be touched, seen or felt. They include ghost, beauty, holiness, mercy, etc.; Provide a passage with concrete and abstract nouns and let learners identify each category.; Have learners use given concrete and abstract nouns in sentences.', 1210),
('Basic 5', 'English Language', 'english', 'Using Writing Conventions/grammar Usage', 'Using action Words', 'B5.5.4.1', 'Demonstrate understanding of verbs in everyday language', 'B5.5.4.1.1', 'Differentiate between how the simple past and the present perfect tense forms are used in speech and in writing', 'Distribute a sample story and let learners identify the simple past verbs to observe how they are used in sentences.; Working in pairs, learners write their own story using the simple past.; Guide learners to do their own editing paying attention to the correct use of the simple past.; Follow the same procedure to guide learners to identify uses of the present perfect tense.; Have learners compare how the two tenses are different.', 1220),
('Basic 5', 'English Language', 'english', 'Using Writing Conventions/grammar Usage', 'Using action Words', 'B5.5.4.1', 'Demonstrate understanding of verbs in everyday language', 'B5.5.4.1.2', 'Use the simple past verb form to express past needs, feelings and interest', 'Let learners write on a story. E.g. What happened after school on Monday?; Discus the essay topic with learners and use the webbing strategy to help them write on the chosen topic. Learners write individually.; Learners exchange their work and edit as teacher guides by focusing on the past verb form and past participle form..; Guide learners to rewrite the essay incorporating the corrections.; Let learners write on another topic individually using the past verb form.', 1230),
('Basic 5', 'English Language', 'english', 'Using Writing Conventions/grammar Usage', 'Using action Words', 'B5.5.4.1', 'Demonstrate understanding of verbs in everyday language', 'B5.5.4.1.3', 'Use past perfect in speech and in writing', 'Narrate an event in the past.; Discuss the narration and have learners identify sentences that are in the simple past and those in the past perfect.; Put learners in groups to write their own narratives on a given topic making use of both simple past and past perfect sentences.; Have groups share their work with the class.', 1240),
('Basic 5', 'English Language', 'english', 'Using Writing Conventions/grammar Usage', 'Using action Words', 'B5.5.4.1', 'Demonstrate understanding of verbs in everyday language', 'B5.5.4.1.4', 'Use singular and plural subjects and the verb forms that go with them. Note: Let learners use the various tenses(simple, present perfect and past perfect)', 'Revise work done on subject-verb agreement and give additional practice.; Review the listed tenses.; Demonstrate that more than one of these may be used in an essay, e.g. the simple present and the simple past as well as simple past and the past perfect.; Show samples of texts from their reader and elsewhere.; Provide topics for learners to practise with their groups.', 1250),
('Basic 5', 'English Language', 'english', 'Using Writing Conventions/grammar Usage', 'Using Qualifying Words-Adjectives', 'B5.5.5.1', 'Demonstrate understanding of adjectives in speech and in writing', 'B5.5.5.1.1', 'Use comparative forms of regular and irregular adjectives to make comparisons', 'Show a picture of a family and guide the learners to talk about the people using the positive comparative and superlative forms of adjectives.; In groups, learners write a description of the members in each group. Let them edit their work focusing on the use of forms of adjectives appropriately.; Learners can add the group picture to their presentation and publish in their class magazine.; Learners now write individually by describing the members of their nuclear families demonstrating their knowledge of the positive, comparative and superlative forms.', 1260),
('Basic 5', 'English Language', 'english', 'Using Writing Conventions/grammar Usage', 'Using Adverbs', 'B5.5.6.1', 'Demonstrate understanding of the use of adverbs in speech and in writing', 'B5.5.6.1.1', 'Use adverbs to express manner', 'Revise verbs and adverbs of place, time and manner.; Provide a passage with adverbs of manner.; Have learners identify the adverbs and their functions – modifying verbs. E.g. Mercy ate slowly.; Pair up learners to write short paragraphs using adverbs of manner.; Have pairs present their work to the class for feedback.', 1270),
('Basic 5', 'English Language', 'english', 'Using Writing Conventions/grammar Usage', 'Using Simple Prepositions', 'B5.5.7.1', 'Apply the knowledge of prepositions in oral and written communication', 'B5.5.7.1.1', 'Use prepositions to convey a variety of meanings', 'Use prepositions in sentences to convey the following meanings: − Position e.g. on − Direction e.g. to − Time e.g. at − Purpose e.g. for − Possession e.g. for − Comparison e.g. taller than − Support or opposition e.g. for you, against you; Provide a text and guide learners with examples to identify positions used to show the following meanings.; Let learners construct sentences to convey the following uses of prepositions, to show: i. Position – she is standing by the car. ii. Direction – They went towards the East. iii. Time – He left at dawn. iv. Purpose – I bought this hoe for weeding my garden. v. Possession – The shirt is for Kofi vi. Comparison vii. Support or opposition – My views are against his plans.; Have learners write a short paragraph containing examples of the prepositions discussed.', 1280),
('Basic 5', 'English Language', 'english', 'Using Writing Conventions/grammar Usage', 'Using Conjunctions', 'B5.5.8.1', 'Apply the knowledge of conjunctions in speech and in writing', 'B5.5.8.1.1', 'Identify and use conjunctions', '– because, since, so, although – to − give reasons − link contrasting ideas − show results; Revise simple conjunctions. Provide simple sentences and let learners join them using and, or/nor, but.; Introduce because, since, so, although, in context. e.g. I''m late because I missed the bus. Although Afi is has eye problems, she doesn''t wear glasses. He eats well, so he is healthy.; Guide learners to discover the functions of these conjunctions.; Have them practise using these conjunctions in their own sentences.; Provide a passage and have learners identify the conjunctions in the passage.; Let learners form sentences and join them with the conjunctions identified.', 1290),
('Basic 5', 'English Language', 'english', 'Using Writing Conventions/grammar Usage', 'Using Simple, Compound and Complex Sentences', 'B5.5.9.1', 'Apply knowledge of grammatical rules to form words, phrases and sentences', 'B5.5.9.1.1', 'Identify subjects and predicates in compound sentences', 'Give learners an extract from a comprehension passage.; Guide them to identify the simple and compound sentences.; Let them identify the subjects and verbs in each compound sentence.; Let learners write about an event they had participated in, demonstrating their understanding of subject and predicate sentences.; Learners edit to demonstrate their knowledge of subject and predicate.', 1300),
('Basic 5', 'English Language', 'english', 'Using Writing Conventions/grammar Usage', 'Using Simple, Compound and Complex Sentences', 'B5.5.9.1', 'Apply knowledge of grammatical rules to form words, phrases and sentences', 'B5.5.9.1.2', 'Construct compound sentences correctly', 'Review the use of coordinators in sentences.; Learners write examples of sentences containing coordinates. Let them write sentences demonstrating their knowledge in subject and predicate.; Learners in groups write a narrative exhibiting their knowledge of subject and predicate in compound sentences.; Guide them to edit their work and encourage them to share the final products with the class.', 1310),
('Basic 5', 'English Language', 'english', 'Using Writing Conventions/grammar Usage', 'Spelling', 'B5.5.10.1', 'Spell words correctly', 'B5.5.10.1.1', 'Use phonics knowledge to spell words', 'In groups, learners plan a spelling activity. Each selects a number of words. Learners create a context E.g. i. It is eaten at Christmas. ii. It is made of flour, eggs, sugar etc. iii. It is baked.; Learners identify the word, say it, spell and use it in a sentence. This is a writing activity that can be done among two groups.; The scores are recorded and the champions rewarded.', 1320),
('Basic 5', 'English Language', 'english', 'Extensive Reading', 'Building the Love and Culture of Reading', 'B5.6.1.1', 'Read widely for pleasure, and to demonstrate independent reading and learning in the literary/content areas', 'B5.6.1.1.1', 'Read a variety of age- and level appropriate books and present at least a-three-paragraph summary of each book read', 'Have learners read independently books of their choice during the library period.; Learners think-pair-share their stories with peers.; Ask each learner to write a-two-three paragraph summary of the book read.; Invite individuals to present their work to the class for feedback.', 1330),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Songs', 'B5.1.1.1', 'Show an understanding of cradle songs/lullaby', 'B5.1.1.1.1', 'Sing cradle songs/lullaby with the correct rhythms and discuss importance of cradle songs/lullaby to the baby, mother and caretaker', 'Show a clip of a baby crying to learners.; Ask learners to tell you what a mother does when a child is crying.; Discuss the answers with the learners and talk about what a lullaby is.; Play a recorded cradle song or lullaby to the hearing of learners.; Lead learners to sing cradle songs/lullaby with correct rhythm.; Allow individual learners to sing a lullaby.; Let learners brainstorm the importance of lullaby.; Lead them to discuss the importance of cradle songs to the baby.; Write some of the benefits discussed on the board, and allow learners to copy them into books. E.g. It makes the baby sleep. It makes the baby happy. It enables the baby to play.; Assist learners to discuss the importance of cradle songs to the mother and caretaker. E.g. It allows the mother to do her work. It helps the mother to rest etc.; Write the outcome from the discussion with the learners.; Let learners role play mother singing a lullaby and holding a child.', 10),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Poems', 'B5.1.3.1', 'Demonstrate knowledge and understanding of selected poems by discussing them', 'B5.1.3.1.1', 'Explore a poem of about six to seven lines correctly', 'Ask a learner to explore a poem and listen to a poem accompanied by audio.; Let the learners perform the gestures that accompany the poems.; Explore a poem for learners to listen.; Lead learners to explore poems correctly.', 20),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Poems', 'B5.1.3.1', 'Demonstrate knowledge and understanding of selected poems by discussing them', 'B5.1.3.1.2', 'Recognise the key words in the poem and discuss the theme of the poem', 'Let learners listen to a poem recital.; Read a poem and discuss key issues in the poem.; Let learners explore poems they know.; Lead learners to recognise the key words in the poem they explore.; Put learners into groups and let the groups discuss the key issues and present to the class.; Allow a learner to explore a poem for learners to listen.; Allow learners to write down what they think about the poem and let them discuss.; In groups, help learners to discuss the theme of the poem.', 30),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Listening and Story Telling', 'B5.1.4.1', 'Demonstrate knowledge on the structure and features of folktales', 'B5.1.4.1.1', 'Retell a folktale of about five scenes and discuss the moral/values of it', 'Ask learners to say what is done in the evenings when there are no electrical gadgets around.; Discuss answers with learners and talk about folktales.; Tell a folktale to learners.; Allow learners to retell the folktale.; Allow learners to discuss the structure of, and the values/moral lessons in the folktale.', 40),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Listening and Story Telling', 'B5.1.4.1', 'Demonstrate knowledge on the structure and features of folktales', 'B5.1.4.1.2', 'Recognise the characters in the folktales', 'Let a learner tell a folktale and discuss key issues among themselves.; Allow learners to recognise the characters in the folktales.; Let learners write briefly on the characters identified.', 50),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Dramatisation and Role Play', 'B5.1.5.1', 'Demonstrate an understanding of how a story can be changed into a drama', 'B5.1.5.1.1', 'Narrate a story of about six to seven characters and recognise the characters, setting and stage', 'Assist learners to read a story of about three paragraphs long.; Discuss some unfamiliar words with learners.; Let learner retell the story in groups.; Discuss key considerations in issues in changing a story to a drama.; Show a video clip to learners.; Put learners in groups to retell the story.; Discuss with learners the features of a drama.; Show learners the processes involved in changing a story into drama.; Assist learners to recognise the characters, setting, costumes and the stage in a drama composed from the story.', 60),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Dramatisation and Role Play', 'B5.1.5.1', 'Demonstrate an understanding of how a story can be changed into a drama', 'B5.1.5.1.3', 'Perform a drama of about six to seven characters', 'Revise the features of a drama and the processes or ways to change a story into a drama.; Let learners mention some of the key points to be considered in turning a story into a drama.; Direct learners to perform a drama piece with the story line.', 70),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Conversation', 'B5.1.6.1', 'Name and discuss some basic items used at home and in school', 'B5.1.6.1.1', 'Recognise and discuss items used at home', 'Show learners pictures or concrete objects of items at home.; Ask learners to mention the names of the things and write them on the board. E.g. bucket, plates, stool, cooking pot, spoon, etc.; Let learners discuss the uses of the items in the home.; Ask learners to improvise the use of some of the home items to the class.; Let learners describe some of the items to the class.', 80),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Conversation', 'B5.1.6.1', 'Name and discuss some basic items used at home and in school', 'B5.1.6.1.2', 'Recognise and discuss things used at school', 'Take learners round the school environment.; Ask learners to tell you some items learners saw when they return to the classroom.; Show learners pictures or concrete objects of items at school.; Ask learners to mention the names of the things and write them on the board. E.g. books, chalk, pens, chairs, table, etc.; In groups, let learners describe the items and their uses.; Let learners tell which people use the items.; Allow learners to put some of the names of the items into both oral and written sentences.', 90),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Conversation', 'B5.1.6.1', 'Name and discuss some basic items used at home and in school', 'B5.1.6.1.3', 'Demonstrate how some of the items used at home and in school are maintained', 'Show learners items found at school and at home.; Pick one of the items and show learners how the item is maintained.; Help learners to demonstrate how some of the items used at home and in school are maintained.; Put learners in groups and let learners present to the class how an item is maintained and its benefits that come with maintenance.', 100),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Talking about Oneself, Family, People and Places', 'B5.1.7.1', 'Demonstrate knowledge on the recognition of expressions and behaviour that show courtesies', 'B5.1.7.1.1', 'Demonstrate and say expressions that show courtesy', 'Show a video that exhibits some courtesy behaviour.; Discuss the video with learners.; Let learners mention some of the words/ expressions heard from the video that indicate courtesy.; Allow learners to write the expressions on the board.; Call learners to read the expressions aloud. Saying “Please”. “I am sorry.” “thank you.” “Excuse me.”; Ask learners to mention other courtesies known to learners.; Let learners mention situations where courtesy is demanded.; Demonstrate some behaviour of courtesy with some of the learners in a mentioned situation.; Direct learners to demonstrate behaviours that indicate courtesy in other situations individually or in groups.', 110),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Talking about Oneself, Family, People and Places', 'B5.1.7.1', 'Demonstrate knowledge on the recognition of expressions and behaviour that show courtesies', 'B5.1.7.1.3', 'Demonstrate non-verbal behaviour that depict courtesy', 'Demonstrate some non-verbal behaviours of courtesy.; Ask learners to discuss the non-verbal action performed.; Listen and write some of the expressions that resulted from the discussion with learners.; Direct learners to demonstrate non-verbal behaviours that depict courtesy.; In groups, allow learners to tell what the non-verbal action depicts in groups.', 120),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Asking and Answering Questions', 'B5.1.9.1', 'Demonstrate knowledge on understanding and use of polar question markers', 'B5.1.9.1.1', 'Recognise and use polar question markers', 'Discuss with learners ways of forming questions.; Ask learners to form questions orally and write them on the board.; Talk about the polar question type.; Write more questions on the board.; Lead learners to recognise polar questions markers from the writing on the board. E.g. Have you eaten? Yes/No Are you from this town? Yes/No', 130),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Asking and Answering Questions', 'B5.1.9.1', 'Demonstrate knowledge on understanding and use of polar question markers', 'B5.1.9.1.2', 'Explain and use polar question markers', 'Write some polar questions on the board.; Ask learners to recognise the polar question markers; Lead learners to use polar question markers identified correctly in their speech or in their conversations.; Ask learners to give more polar questions.; Write some of the polar questions on the board.; Help learners to recognise the polar question markers and tell where they occur in the structure.; Ask learners to tell how to use polar question markers correctly.; Allow learners to give examples on the board.', 140),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Giving and Following Commands/Instructions', 'B5.1.10.1', 'Exhibit knowledge of understanding and use of landmarks in giving directions', 'B5.1.10.1.1', 'Recognise landmarks in your area and other areas', 'Discuss with learners what landmarks are.; Display a sketch of an area on the board.; Show them some of the landmarks on the sketch.; Lead learners to recognise landmarks in their area and other areas.; Allow a learner to give directions to their home making reference to any landmark in their area. E.g. post office, palace, church, mosque, school etc.', 150),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Giving and Following Commands/Instructions', 'B5.1.10.1', 'Exhibit knowledge of understanding and use of landmarks in giving directions', 'B5.1.10.1.2', 'Use landmarks to give directions', 'Display a sketch of an area on the board.; Ask the learners to mention some of the landmarks seen on the sketch displayed.; Point to two locations on the sketch and ask learners to give directions from one location to another point on the sketch.; Assist learners to use more landmarks on the sketch to give directions correctly. E.g. Take the route on your right. Turn to the left of the mosque and descend the hill near the post office.; Expose learners to Global Positioning System (GPS), especially the Ghana Post digital address system.; Show learners how to use it.', 160),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Giving and Following Commands/Instructions', 'B5.1.11.1', 'Demonstrate an understanding of the process of cleaning the home', 'B5.1.11.1.1', 'Discuss things that make the home unclean', 'Display a picture of a rubbish dump and another picture of a neat house.; Let learners talk about the pictures in groups.; Lead learners to recognise and mention things that make the home unclean.; Let learners draw some of the things that make the home unclean. E.g. Rubbish, stagnant water, unclean bowls etc.', 170),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Giving and Following Commands/Instructions', 'B5.1.11.1', 'Demonstrate an understanding of the process of cleaning the home', 'B5.1.11.1.2', 'Discuss the items used in cleaning the home', 'Display a picture of somebody sweeping.; Let learners talk about the picture.; Lead a discussion on cleanliness.; Allow learners to recognise and mention items used in cleaning the home.; Show some items for cleaning to the learners.; Let learners demonstrate or improvise the use of these items in a cleaning exercise. E.g. Broom, mop, dusters, etc.', 180),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Giving and Following Commands/Instructions', 'B5.1.11.1', 'Demonstrate an understanding of the process of cleaning the home', 'B5.1.11.1.3', 'Give reasons for cleaning the home', 'Discuss with learners the consequences of an unclean home.; Lead learners to discuss how to make the home clean.; Help learners to recognise and mention the reasons for cleaning the home. E.g. To make the home healthy for living. To prevent sickness etc.', 190),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter and sound knowledge', 'B5.2.4.1', 'Demonstrate the ability to listen to and pronounce words with identical sounds from a list of words', 'B5.2.4.1.1', 'Read and recognise words with familiar sounds', 'Ask learners to mention some sounds of the letters of the alphabet.; Write down some of these sounds on the board.; Select one sound and lead learners to form words using that sound.; Read to learners words with familiar sounds.; Assist learners to read and recognise word with familiar sounds at word medial.; Read to learners some simple poems.; In groups, lead learners to read simple poems of about ten lines.; Ask learners to note the words in the poems that have similar sounds.; Group the words identified and categorise them into words with similar sounds.', 200),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter and sound knowledge', 'B5.2.4.1', 'Demonstrate the ability to listen to and pronounce words with identical sounds from a list of words', 'B5.2.4.1.2', 'Read and recognise diagraphs in words found in paragraphs', 'Let learners mention some words and write them on the board.; Group the words into two: those without diagraphs and those with diagraphs.; Write out the diagraphs on the board and pronounce them to the hearing of learners.; Assist learners to recognise diagraphs in the words in a given paragraph.; Call learners to write the diagraphs identified from the words on the board.; Group the diagraphs and put learners into groups and ask learners to form more words with the diagraph assigned to each group.', 210),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter and sound knowledge', 'B5.2.4.1', 'Demonstrate the ability to listen to and pronounce words with identical sounds from a list of words', 'B5.2.4.1.3', 'Blend two or more syllables to form words and read them', 'Let learners mention some words and write them on the board.; Divide the words into syllables and discuss with learners.; Allow learners to use some of the syllables to form new words.; Let learners say the words to the class and write some on the board. .; Assist learners to blend two or more syllables to form words and read them.; Let learners use some of the words to form sentences orally.', 220),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Vocabulary (Sight and content vocabulary)', 'B5.2.5.1', 'Show an understanding of recognising and reading about things in their environment', 'B5.2.5.1.1', 'Read paragraphs of passages aloud with correct pronunciation and tone', 'Write some sentences on flashcards and show them to learners.; Ask some of the learners to say the words and then read the sentences in full.; In groups, guide learners to read sentences aloud with correct pronunciation and tone.; Give a paragraph of a passage and allow learners to read in turns.; With sentences card and learners in groups, help learners to read paragraphs aloud with correct pronunciation and tone.; Give passages of about three paragraphs, and let learners read in their groups.; Call leaders of the groups to read the whole passage to the class.', 230),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Vocabulary (Sight and content vocabulary)', 'B5.2.5.1', 'Show an understanding of recognising and reading about things in their environment', 'B5.2.5.1.2', 'Read stories aloud with correct pronunciation and tone', 'Put learners in groups to read sample notices, texts and use sentence cards to help learners read paragraphs aloud with correct pronunciation and tone.', 240),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Comprehension', 'B5.2.6.1', 'Exhibit knowledge of answering questions based on texts presented', 'B5.2.6.1.1', 'Explain the meaning of unfamiliar words in context', 'Put learners in groups and read a passage aloud to them.; Ask learners to read the passage on their own and recognise unfamiliar words.; Let learners say the unfamiliar words and write them on the board.; Assist the learners to explain the meanings of the unfamiliar words from their context.; Let learners use some of the unfamiliar words to form sentences orally.', 250),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Comprehension', 'B5.2.6.1', 'Exhibit knowledge of answering questions based on texts presented', 'B5.2.6.1.2', 'Answer factual and inferential questions', 'Read a passage aloud.; Allow learners to read the passage on their own.; Call learners to read a paragraph each of the passage aloud to the class.; Let the learners answer factual and inferential questions based on the passage.', 260),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Silent Reading', 'B5.2.7.1', 'Demonstrate knowledge on reading for comprehension', 'B5.2.7.1.1', 'Explain the meaning of unfamiliar words in a text', 'Read a passage of about four paragraphs aloud in class.; Let learners read the passage silently for a few minutes.; Assist the learners to explain the meanings of unfamiliar words in the text.', 270),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Silent Reading', 'B5.2.7.1', 'Demonstrate knowledge on reading for comprehension', 'B5.2.7.1.2', 'Explain the meaning of figurative expression in a text and answer questions on the passage', 'Read a passage consisting of more than five paragraphs aloud.; Ask learners to read and recognise some figurative expressions from the passage.; Point out to learners some of the figurative expressions in the passage that you read to them.; Guide the learners to explain meanings of figurative expressions in a text.; Allow learners to read a paragraph each.; In groups, let learners read the passage and tell what understanding learners get.; Guide the learners to answer questions based on the passage.', 280),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Fluency', 'B5.2.8.1', 'Exhibit the ability to read longer texts with minimal mistakes', 'B5.2.8.1.1', 'Read longer texts with minimal mistakes', 'Give learners longer passages to read aloud.; Help learners read longer passages with minimal mistakes.; Let learners recognise unfamiliar words and discuss with learners.; Play a reading game with learners in groups and in pairs.', 290),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Fluency', 'B5.2.8.1', 'Exhibit the ability to read longer texts with minimal mistakes', 'B5.2.8.1.2', 'Read naturally', 'Give learners longer passages to read aloud.; Help learners read longer passages silently with minimal mistakes. Ask learners to note unfamiliar words and explain to learners individually as teacher moves from learner to learner during the reading.', 300),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Summarising', 'B5.2.9.1', 'Show an understanding of how main ideas are extracted from a text', 'B5.2.9.1.1', 'Give the summary of longer texts', 'Let learners read a passage.; Let learners recognise the main ideas in each paragraph read.; Let learners write down each idea found in each paragraph and discuss in their groups.; Assist learners to recognise the main ideas in a text.; Lead learners to give summaries of the texts orally before writing in their books.', 310),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Summarising', 'B5.2.9.1', 'Show an understanding of how main ideas are extracted from a text', 'B5.2.9.1.2', 'Write main ideas in a given text', 'Read a text aloud in class.; Let learners select the main ideas from each paragraph.; Let learners write the main ideas in their own words and read aloud for discussion.; Assist learners to write the main ideas in the given text in simple sentences correctly.', 320),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Penmanship/Handwriting', 'B5.3.1.1', 'Exhibit knowledge in the use of full stops, commas and question marks appropriately in sentences; and write simple sentences boldly and clearly', 'B5.3.1.1.1', 'Recognise the use of full stops at the end of a complete sentence, and to separate initials', 'Let learners write a sentences on the board and in their books.; Go round and check the sentences written to see if full stops are at the ends.; Discuss the punctuation, full stop, with learners.; Write a passage on the board with all punctuations.; Assist learners to recognise that a full stop is used at the end of a complete sentence, and to separate initials.', 330),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Penmanship/Handwriting', 'B5.3.1.1', 'Exhibit knowledge in the use of full stops, commas and question marks appropriately in sentences; and write simple sentences boldly and clearly', 'B5.3.1.1.2', 'Recognise that a comma is used to separate a list of items. It serves as a pause in sentences and speech', 'Write a passage on the board with all the appropriate punctuations.; Discuss the passage with learners, and help them to recognize the punctuation comma.; Assist learners to recognise that a comma is used to separate a list of items. It serves as a pause in sentences and speech.; Let learners write sentences or short passages using the comma.; Write a list of items on the board and ask learners to use the list to form sentences, using the comma to separate the items in the sentence written.', 340),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Penmanship/Handwriting', 'B5.3.1.1', 'Exhibit knowledge in the use of full stops, commas and question marks appropriately in sentences; and write simple sentences boldly and clearly', 'B5.3.1.1.3', 'Recognise that a colon is used to list and explain a statement, or to mention a list of items', 'Write a passage on the board with all the appropriate punctuations.; Discuss the use of the colon in the passage.; Assist learners to recognise that a colon is used to list and explain a statement, or to mention a list of items.', 350),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Penmanship/Handwriting', 'B5.3.1.1', 'Exhibit knowledge in the use of full stops, commas and question marks appropriately in sentences; and write simple sentences boldly and clearly', 'B5.3.1.1.4', 'Recognise that quotation marks are used when you want to write or quote the same words a person said or wrote', 'Call learners to make some utterances by asking questions.; Write the utterance in quotation marks on the board and discuss with learners.; Write a passage on the board with all punctuations.; Assist learners to recognise that, quotation marks are used when you want to write the same words a person said or wrote.', 360),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Penmanship/Handwriting', 'B5.3.1.1', 'Exhibit knowledge in the use of full stops, commas and question marks appropriately in sentences; and write simple sentences boldly and clearly', 'B5.3.1.1.5', 'Write simple sentences', 'Write words on the boards and explain the meaning of those words.; Call learners in turns to form simple sentences with the words.; Write sentences on sentence cards.; Use the sentence cards to help learners write simple and meaningful sentences.', 370),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Narrative Writing', 'B5.4.1.1', 'Comprehend and use punctuation marks in narrative writing', 'B5.4.1.1.1', 'Recognise and use commas, full stops, and question marks appropriately in narrative writing', 'Discuss with learners types of writing and explain what narrative writing is.; Give examples of narrative writing to learners to examine.; Discuss with learners the structure and features of narrative writing.; Assist learners to recognise the use of commas, full stops, and question marks appropriately in narrative writing given.; Allow learners to write a narrative of about two hundred words.', 380),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Narrative Writing', 'B5.4.1.1', 'Comprehend and use punctuation marks in narrative writing', 'B5.4.1.1.2', 'Understand and use exclamation mark in narrative writing appropriately', 'Give a long narrative writing piece to learners.; Discuss the content of the narrative writing with learners.; Allow learners to recognise the exclamation marks used in the given piece.; Let learners read the narrative piece in their groups.; Assist learners to understand the use of exclamation marks in narrative writing appropriately.', 390),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Narrative Writing', 'B5.4.1.1', 'Comprehend and use punctuation marks in narrative writing', 'B5.4.1.1.3', 'Know the appropriate use of colon and quotation marks in narrative writing', 'With a given narrative writing piece.; Allow learners to discuss in groups the punctuations used in the narrative writing.; Assist learners to know the use of the colon and quotation marks in narrative writing appropriately through discussion.', 400),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Creative/ Free Writing', 'B5.4.2.1', 'Show an understanding of creating and writing longer stories on their own', 'B5.4.2.1.1', 'Write a short story on their own', 'Discuss with learners things that are considered in writing a story.; In groups, ask learners to create a short story and read to the class.; Give a few words on the board as a guide for learners to write a short story.', 410),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Creative/ Free Writing', 'B5.4.2.1', 'Show an understanding of creating and writing longer stories on their own', 'B5.4.2.1.2', 'Write an imaginative longer story on their own', 'Ask a learner to tell a story.; Discuss with learners what an imaginative story is.; In groups, ask learners to write an imaginative story of about three hundred words and present to the class.; Write sentences on flashcards.; Use the sentences on the flashcards to help learners to write an imaginative longer story on their own.', 420),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Creative/ Free Writing', 'B5.4.2.1', 'Show an understanding of creating and writing longer stories on their own', 'B5.4.2.1.3', 'Create a story that relates to their environment', 'Discuss some environmental issues with learners such as flood, bushfire, climate change pollution, etc. Give learners some guiding sentences on the board.; Put learners in groups and guide them to create a story about a selected issue on the environment for each group.', 430),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Descriptive Writing', 'B5.4.3.1', 'Exhibit knowledge of writing descriptive essays using controlled composition or on their own', 'B5.4.3.1.1', 'Write simple descriptive essays about human beings using controlled composition', 'Use controlled composition to write a short descriptive essay on a cardboard.; Encourage and monitor learners to write simple descriptive essays about human beings using controlled composition.', 440),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Descriptive Writing', 'B5.4.3.1', 'Exhibit knowledge of writing descriptive essays using controlled composition or on their own', 'B5.4.3.1.2', 'Give simple descriptive essays about objects using controlled composition', 'Use controlled composition to write a simple descriptive essay on a cardboard.; Let learners write simple descriptive essays about objects using controlled composition.', 450),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Descriptive Writing', 'B5.4.3.1', 'Exhibit knowledge of writing descriptive essays using controlled composition or on their own', 'B5.4.3.1.3', 'Write their own simple descriptive essays on given topics', 'Use controlled composition to write a simple descriptive essay on a cardboard.; Guide learners to write simple descriptive essays on given topics of at least three paragraphs and read some aloud in class.', 460),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Persuasive Writing', 'B5.4.4.1', 'Exhibit knowledge of writing simple persuasive essays using controlled composition on their own', 'B5.4.4.1.1', 'Write a simple persuasive essay through controlled composition', 'Use controlled composition to write a simple persuasive essay on a cardboard.; Read the sample persuasive essays on the cardboard and discuss some of its structure and features.; Let learners compose a simple persuasive essay through controlled composition individually and read some aloud to class.', 470),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Persuasive Writing', 'B5.4.4.1', 'Exhibit knowledge of writing simple persuasive essays using controlled composition on their own', 'B5.4.4.1.2', 'Write simple persuasive essays about domestic issues', 'Discuss domestic issues with learners.; Use controlled composition to write a simple persuasive essay on a cardboard.; Allow learners to write simple persuasive essays about domestic issues.', 480),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Persuasive Writing', 'B5.4.4.1', 'Exhibit knowledge of writing simple persuasive essays using controlled composition on their own', 'B5.4.4.1.3', 'Write persuasive essays on given topics', 'Use controlled composition to write a simple persuasive essay on a cardboard.; Guide learners to write persuasive essays on given topics.', 490),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Argumentative Writing', 'B5.4.5.1', 'Exhibit knowledge and understanding of good argumentative essays by gathering information', 'B5.4.5.1.1', 'Gather information for the writing of good argumentative essays', 'Discuss the structure of argumentative writing with learners.; Use controlled composition to write a simple argumentative essay on a cardboard.; Read the argumentative essay on the board pointing out the structure.; Let learners understand and recognise how to gather information for the writing of good argumentative essays.', 500),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Argumentative Writing', 'B5.4.5.1', 'Exhibit knowledge and understanding of good argumentative essays by gathering information', 'B5.4.5.1.2', 'Comprehend and discuss how to write for or against a motion in an argumentative essay', 'Give a topic to the class and put the learners into two groups.; Let one group write for the topic and the other against the topic in class.; Let each group read their write up in class.; Discuss the ways of writing for or against a motion in a given motion in an argumentative essay.; Let individual learners write for or against a given motion.', 510),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Argumentative Writing', 'B5.4.5.1', 'Exhibit knowledge and understanding of good argumentative essays by gathering information', 'B5.4.5.1.3', 'Write a simple argumentative essay on a given topic', 'Use controlled composition to write a simple argumentative essay on a cardboard.; Guide learners to write a simple argumentative essay on a given topic of about four paragraphs.', 520),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Informative/ Academic Writing', 'B5.4.6.1', 'Demonstrate knowledge of creating a journal', 'B5.4.6.1.1', 'Write articles for a journal and edit the articles', 'Show learners a copy of an article.; Discuss with learners some types of articles and their structure.; Discuss with learners what a journal is.; Talk to learners about types of journals.; Guide learners to write a simple article in their groups, and discuss in class.; Create a class journal.; Let learners write articles for their class journal.; Show learners a copy of an article.; Assist learners to edit the articles for their class journal by bringing out the features and structure of the article in the journal.', 530),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Informative/ Academic Writing', 'B5.4.6.1', 'Demonstrate knowledge of creating a journal', 'B5.4.6.1.2', 'Publish and appreciate the articles in the journal', 'Look at the class journal created.; In their groups, let learners write simple articles on topics on disability and equity, and let other learners edit them.; Ask the learners to publish the article in the created class journal and display in the class.; Put learners in groups and allow each group to read an article from the class journal and discuss the article, bringing out for instance, the moral and the theme.', 540),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Literary Writing', 'B5.4.7.1', 'Demonstrate knowledge of creating short literary works', 'B5.4.7.1.1', 'Write short poems', 'Write a simple short poem on a cardboard.; Discuss some features of a poem with learners.; Use flashcards with short poems on them to help learners compose their own short poems.', 550),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Literary Writing', 'B5.4.7.1', 'Demonstrate knowledge of creating short literary works', 'B5.4.7.1.2', 'Create short prose', 'Show learners samples of prose and discuss some features of prose.; Ask learners to write a simple prose to be read in class.; Give an assignment of prose writing as a competition among learners.', 560),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Literary Writing', 'B5.4.7.1', 'Demonstrate knowledge of creating short literary works', 'B5.4.7.1.3', 'Write a short and simple play', 'Allow learners to watch a simple play.; Discuss the play with learners and bring out its features.; Write out some of the features of a play on the board as a guide.; Ask learners to write a simple play of at least three characters, one of the plays may be dramatised in class and be discussed.', 570),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Letter Writing', 'B5.4.8.1', 'Exhibit knowledge in the writing of semi- formal letters', 'B5.4.8.1.1', 'Comprehend and discuss the process in writing good semi-formal letters', 'Discuss letter writing and its structure with learners.; Show a sample of a letter to learners to point out the structure and features.; Discuss the features and types of letters.; Explain to learners the structure of semi-formal letters.; Write a sample semi-formal letter on the board.; Discuss the process involved in writing a semi-formal letter.; Assist learners to understand the process in writing good semi-formal letters.', 580),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Letter Writing', 'B5.4.8.1', 'Exhibit knowledge in the writing of semi- formal letters', 'B5.4.8.1.2', 'Write semi-formal letters using controlled composition', 'Write a semi-formal letter on the board.; Assist learners to write semi-formal letters using controlled composition.; Ask learners to point out the features and structure of the semi-formal letter written.', 590),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Letter Writing', 'B5.4.8.1', 'Exhibit knowledge in the writing of semi- formal letters', 'B5.4.8.1.3', 'Write good semi-formal letters', 'Read a semi-formal letter to learners.; Guide learners to write good semi-formal letters.', 600),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (capitalization)', 'B5.5.1.1', 'Show an understanding in the use of capital letters appropriately', 'B5.5.1.1.1', 'Understand that capital letters begin proper nouns', 'Write a list of words on the board comprising of common nouns and proper nouns.; Ask learners to group the nouns.; Discuss with learners the proper nouns.; Let learners recognise the use of capital letters to begin the proper nouns.; Ask students to write some more proper nouns on the board.; Ask learners to use some of the proper nouns in sentences.', 610),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (capitalization)', 'B5.5.1.1', 'Show an understanding in the use of capital letters appropriately', 'B5.5.1.1.2', 'Comprehend the use of capital letters after a colon', 'Write a paragraph on flash cards with all punctuations used.; Ask learners to recognise where capital letters occur in the paragraph.; Discuss the colon and the use of capitals after the colon.; Use flashcards to help learners understand the use of capital letters after a colon.', 620),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (capitalization)', 'B5.5.1.1', 'Show an understanding in the use of capital letters appropriately', 'B5.5.1.1.3', 'Understand the use of capital letters after a question mark', 'Allow learners to read a passage.; Discuss with learners the occurrences of the question mark in the passage.; Let learners recognise the words that occur after the question mark.; Discuss the occurrence of the capital letter to begin the word after the question mark.; Write a few sentences on the board and ask learners to write them out correctly, placing in them question marks and capital letters, etc.', 630),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Punctuation)', 'B5.5.2.1', 'Demonstrate knowledge in the use of punctuation marks in passages', 'B5.5.2.1.1', 'Recognise and use commas, full stops, and question marks appropriately in writing', 'Show a passage to learners and allow the learners to read.; Read the passage aloud to learners.; Let learners recognise the punctuation used in the passage.; Write a paragraph on a flash card without any punctuations.; Guide learners to use commas, full stops, and question marks appropriately in the writing.', 640),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Punctuation)', 'B5.5.2.1', 'Demonstrate knowledge in the use of punctuation marks in passages', 'B5.5.2.1.2', 'Understand and use exclamation mark in writing appropriately', 'Allow learners to read a passage and discuss the punctuations with learners.; Talk about the exclamation mark.; Write a paragraph on a flash card without some punctuations, e.g. the exclamation mark.; Read the paragraph aloud to learners.; Assist learners to use exclamation marks to punctuate the writing appropriately.', 650),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Punctuation)', 'B5.5.2.1', 'Demonstrate knowledge in the use of punctuation marks in passages', 'B5.5.2.1.3', 'Use colon and quotation marks in writing appropriately', 'Revise the lesson on colon with learners and discuss quotation marks with learners.; Give a short passage and ask learners to put in the colon and quotation marks appropriately.', 660),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of action words)', 'B5.5.3.1', 'Demonstrate knowledge on use of action words appropriately', 'B5.5.3.1.1', 'Recognise and use simple present tense action words in sentences', 'Ask learners to do some actions in the class like clap, jump, sit, etc.; Write and read aloud some of the action words mentioned by the learners.; Ask learners to form sentences orally with some of the action words.; Write simple present tense sentences on flashcards.; Call learners in turns to read out the sentences on the flashcards.; Call a learner to say or point out the action word in the sentence on a flashcard.; Give simple present tense action words to learners to form sentences and read out aloud, or show to the class by writing on the board.', 670),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of action words)', 'B5.5.3.1', 'Demonstrate knowledge on use of action words appropriately', 'B5.5.3.1.2', 'Use simple past tense action words in sentences', 'Ask learners to recount what they did the day before.; Write some of the action words mentioned by the learners on the board.; Read aloud to learners the written action words.; Talk to learners about the action and explain to them the action has happened already.; Allow learners to give more action words orally and guide them to put the words in past tense.; Ask learners to use the past tense action words to form simple sentences in writing, or orally.', 680),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of qualifying words)', 'B5.5.4.1', 'Demonstrate knowledge in the use of adjectives and adverbs', 'B5.5.4.1.1', 'Recognise and use the types of adjectives (dimension, colour, age)', 'Show objects to the class and let learners touch the objects.; Ask learners to describe the objects.; Write on the board some of the words used in describing the objects.; Read aloud the words to learners e.g. blue, big, small, round etc.; Allow learners to use some of the qualifying words to form sentences either written or orally.; Write sentences containing adjectives on flashcards.; Use the flashcards with adjectives written on them to help learners recognise the type of adjectives. (Dimension, colour, physical propensity, age, etc.); Ask learners to mention adjectives and write them on the board.; Allow learners to use some of the adjectives to form sentences.; Ask learners to put the adjectives written on the board into the different types taught to the learners.; Put learners into groups and give each group one type of adjective to form some sentences with them and read aloud to the class.', 690),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of qualifying words)', 'B5.5.4.1', 'Demonstrate knowledge in the use of adjectives and adverbs', 'B5.5.4.1.2', 'Use of comparative and superlative words/adjectives forms in sentences', 'Show two objects of the same type to learners.; Ask learners to compare the objects in terms of size, colour, age, etc.; Write out the words that are used in the sentences to compare the objects in addition to the verb denoting adjectival meaning or the adjective for example in Akan …..’kyen’/sen is a comparative word, Ga uses ‘fe’ for comparing.; Explain to learners that the comparative is done either with the use of a word, or the adjectival form changes depending on the language in question.; Talk about the superlative and discuss the words used in a sentence to tell that the object that is described is superlative e.g. in Ga ‘fefɛɛ’ occurs in the sentence.', 700),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of postpositions)', 'B5.5.5.1', 'Demonstrate the use of postpositions', 'B5.5.5.1.1', 'Recognise and use postpositions in complex sentences', 'Revise postpositions with learners.; Let learners give some examples of postpositions.; Write the postpositions on the board and read them aloud.; Allow learners to form some sentences.; Write sentences with postposition words on flashcards. Read aloud the sentences and allow learners to also read.; Guide learners to recognise post positions in complex sentences.; Allow learners to use some of the written postpositions on the board to form complex sentences.; Explain the structure of a complex sentence to learners.; Assist learners to use postpositions in writing complex sentences.', 710),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of postpositions)', 'B5.5.5.1', 'Demonstrate the use of postpositions', 'B5.5.5.1.3', 'Recognise postpositions in paragraphs', 'Give learners a passage to read or read it to them.; Assist learners to recognise post positions in paragraphs.; Present learners with a mixture of words and allow them to select the postpositions.', 720),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of simple and compound sentences)', 'B5.5.6.1', 'Exhibit knowledge in the use of conjunctions in forming compound sentences', 'B5.5.6.1.1', 'Recognise single conjunctions such as “but” and “because” in compound sentences', 'Ask learners to give simple sentences orally and write the sentences on the board.; Discuss how some of the sentences can be put together as one sentence.; Explain to the learners the use of conjunctions as words used to link the sentences.; Give a sample compound sentence and guide learners to recognise the conjunction in it.; Write out other conjunctions and read aloud to learners.; Use flashcards with single conjunctions written on them to assist learners to recognise single conjunctions such as “but”, “because” in compound sentences.', 730),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of simple and compound sentences)', 'B5.5.6.1', 'Exhibit knowledge in the use of conjunctions in forming compound sentences', 'B5.5.6.1.2', 'Use single conjunctions in forming compound sentences', 'Write a mixture of words on the board and lead learners to select the conjunctions.; Ask learners to use the conjunctions to form compound sentences orally or written.; Put learners in a group to write compound sentences and underline the conjunction.', 740),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of simple and compound sentences)', 'B5.5.6.1', 'Exhibit knowledge in the use of conjunctions in forming compound sentences', 'B5.5.6.1.3', 'Form compound sentences with appropriate conjunctions', 'Give learners simple sentences and ask them to form compound sentences with them using the appropriate conjunction.; Use flashcards with conjunctions written on them to assist learners to form compound sentences with appropriate conjunctions.; Allow learners to write some conjunctions on the board.', 750),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Spelling)', 'B5.5.7.1', 'Recognise and spell out words correctly', 'B5.5.7.1.1', 'Write eight and nine-letter words correctly', 'Ask learners to mention words they know and write them on the board.; Group the words according to the number of letters.; Read the letters aloud and guide learners to spell out the words correctly.; Use flashcards with eight and nine letter words written on them to help learners to write eight and nine letter words correctly.', 760),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Spelling)', 'B5.5.7.1', 'Recognise and spell out words correctly', 'B5.5.7.1.2', 'Rearrange letters to form new words', 'Give learners some letters and ask them to form words from those letters.; Say and write on the board eight, and nine letters and help learners rearrange the letters to form new words.', 770),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Spelling)', 'B5.5.7.1', 'Recognise and spell out words correctly', 'B5.5.7.1.3', 'Fill in missing words from passages', 'Write words with some missing sounds. Let learners recognise them and fill in the missing letters.; Using flashcards with sentences that have missing words written on them help learners fill in missing words from passages.', 780),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language(Conjunctions)', 'B5.5.8.1', 'Apply the knowledge on the use of conjunctions in writing sentences', 'B5.5.8.1.1', 'Identify conjunctions (because, since, so, although etc.) appropriately in sentences to give reasons, link contrasting ideas and show results', 'Revise the lesson on simple conjunctions.; Provide simple sentences and let learners join them using and, or/nor, but.; Introduce because, since, so, although in context. e.g.: I''m late because I missed the bus. Although Afi is has eye problems, she doesn''t wear glasses. He eats well, so he is healthy.; Guide learners to discover the functions of these conjunctions.; Have them practise using these conjunctions in their own sentences.; Provide a passage and have learners identify the conjunctions in the passage.; Let learners form pairs of simple sentences and join them with the conjunctions identified.', 790),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children Literature/Library', 'Building the Love and Culture of Reading in Learners', 'B5.6.1.1', 'Exhibit the ability to read other materials like newspapers, novels, other than the class Reader alone', 'B5.6.1.1.1', 'Read aloud passages from novels and newspapers with correct pronunciation and tone', 'Read a passage aloud to learners.; Use flashcards with three to four word sentences written on them to assist learners with correct pronunciation and intonation.; Let learners bring other materials on literary works like magazines or newspapers to read.; Call learners to read paragraph by paragraph to check the correct pronunciation.', 800),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children Literature/Library', 'Building the Love and Culture of Reading in Learners', 'B5.6.1.1', 'Exhibit the ability to read other materials like newspapers, novels, other than the class Reader alone', 'B5.6.1.1.2', 'Demonstrate correct speech, rhythm and tone', 'Read a newspaper or novel aloud to learners with the correct tone and rhythm. Allow learners to demonstrate correct speech, rhythm and tone.', 810),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children Literature/Library', 'Read Aloud with Children', 'B5.6.2.1', 'Exhibit knowledge in reading sentences, paragraphs and stories aloud', 'B5.6.2.1.1', 'Read aloud passages with correct pronunciation and tone', 'Read a passage of about seven paragraphs aloud to learners.; Lead learners to read aloud passages with correct pronunciation and intonation.', 820),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children Literature/Library', 'Read Aloud with Children', 'B5.6.2.1', 'Exhibit knowledge in reading sentences, paragraphs and stories aloud', 'B5.6.2.1.2', 'Demonstrate correct speech, rhythm and tone', 'Demonstrate correct speech, rhythm and tone.; Lead learners to demonstrate correct speech, rhythm and tone.', 830),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children Literature/Library', 'Reading Texts, Poems, Narrative, and Short Stories and Respond to them', 'B5.6.3.1', 'Demonstrate knowledge in reading materials other than the reader provided in class with understanding', 'B5.6.3.1.1', 'Read short texts, narratives or stories from other materials with correct intonation/tone', 'Read a text aloud to the hearing of learners.; Guide learners to read short texts, narratives or stories from other materials with correct intonation.; Let learners read paragraph each of the text to the class.', 840),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children Literature/Library', 'Reading Texts, Poems, Narrative, and Short Stories and Respond to them', 'B5.6.3.1', 'Demonstrate knowledge in reading materials other than the reader provided in class with understanding', 'B5.6.3.1.2', 'Answer questions on the narratives/passage read', 'Learners read a passage to the hearing of others learners.; Lead learners to answer questions on the passage read orally then write them into their books.', 850),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children Literature/Library', 'Reading Texts, Poems, Narrative, and Short Stories and Respond to them', 'B5.6.3.1', 'Demonstrate knowledge in reading materials other than the reader provided in class with understanding', 'B5.6.3.1.3', 'Retell the short stories or narratives read', 'Read a passage to the hearing of learners.; Guide learners to re-tell the short stories or narratives read.', 860),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children Literature/Library', 'Reading Texts, Poems, Narrative, and Short Stories and Respond to them', 'B5.6.3.1', 'Demonstrate knowledge in reading materials other than the reader provided in class with understanding', 'B5.6.3.1.4', 'Read paragraphs, passages and stories of different texts', 'Read a paragraph to the hearing of learners.; Give learners the opportunity to read paragraphs, passages and stories of different texts to the class.', 870),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children Literature/Library', 'Reading Texts, Poems, Narrative, and Short Stories and Respond to them', 'B5.6.3.1', 'Demonstrate knowledge in reading materials other than the reader provided in class with understanding', 'B5.6.3.1.5', 'Answer factual questions based on the passage read', 'Read a passage to the hearing of learners.; Help learners to read a text.; Let them answer factual questions based on the passage read.; Ask learners to narrate what they read.', 880),
('Basic 5', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children Literature/Library', 'Reading Texts, Poems, Narrative, and Short Stories and Respond to them', 'B5.6.3.1', 'Demonstrate knowledge in reading materials other than the reader provided in class with understanding', 'B5.6.3.1.6', 'Write a summary of passage/text read', 'Read a passage to the hearing of learners.; Lead learners to read a text.; Guide them to summarize the passage read', 890),
('Basic 5', 'History', 'history', 'My Country Ghana', 'The People Of Ghana', 'B5.2.1.1', 'Demonstrate understanding of how life in ancient time was different from life today', 'B5.2.1.1.1', 'Describe how our ancestors lived in ancient times (before the 15th century) and compare it with how we live today. Enquiry route: How did our ancestors live? Compare how our ancestors lived and how we live today? What things have changed? What things remain similar?', '1. Identify the kinds of food they ate, the clothes they wore and how they travelled etc.; 2. Compare life today to life in ancient days. E.g. Food eaten, Clothes worn, Mode of travel, buildings Communication, Trading, Professions and Technology.; 3. Produce a photo album (Tactile photo album for visually impaired) of family members including learners; 4. Visit ancient sites and museums; 5. Use videos/ documentaries/internet to highlight how life today has changed from the past', 10),
('Basic 5', 'History', 'history', 'My Country Ghana', 'The People Of Ghana', 'B5.2.1.1', 'Demonstrate understanding of how life in ancient time was different from life today', 'B5.2.1.1.2', 'Describe some ancient towns in Ghana. : Which were the ancient towns in Ghana? Where were they located? Who founded them?', '1. List some ancient towns and places in Ghana (Begho, Bono- Manso, Dawhenya, Eguafo, Kintampo, Salaga, Daboya); 2. Locate some of these towns and places on a map of Ghana; 3. Use the internet to learn about these places and share in class; 4. Show and discuss a documentary/pictures of some of these towns and places', 20),
('Basic 5', 'History', 'history', 'My Country Ghana', 'Some Selected Individuals', 'B5.2.5.1', 'Demonstrate knowledge of Ghanaians who made significant contributions locally and internationally 3', 'B5.2.5.1.1', 'Name Ghanaians who have made significant Contribution locally and internationally including Dr R.E.G Armattoe (Science and Medicine), Kofi Annan-international diplomacy, Osibisa- popular music, El Anatsui', '– sculptor, David Adjaye -architect, Ozwald Boateng-fashion, Efua Sutherland- playwright, Prof Francis Allotey- science and History, Prof Akua Kuenyehia- law, Prof. Frimpong Boateng – Surgeon, Abedi Ayew ‘Pele’ – Football, Azumah Nelson – Boxing etc. Enquiry Route: which individuals have contributed locally and internationally? What were their contributions? Which among them inspires you most and why?; 1. Use pictures, posters or the internet to identify Ghanaian who have made important contributions locally and internationally.; 2. Match these personalities with areas of specialty e.g. Dr R.E.G Armattoe (Science and Medicine), Kofi Annan-international diplomacy, Osibisa- popular music, El Anatsui – sculptor, David Adjaye- Architect, Ozwald Boateng-fashion, Efua Sutherland- playwright, Prof Francis Allotey- science and History, Prof Akua Kuenyehia- law, Prof. Frimpong Boateng – Surgeon, Abedi Ayew ‘Pele’ – Football, Azumah Nelson -Boxing etc.; 3. Show photographs/ documentary of significant individuals; 4. Retell the live stories of any of these from a documentary show; 5. With the aid of the internet learners are to develop a documentary/poster of individuals who have contributed significantly in this field; 6. Identify the traditional rulers whose work inspires you most and give reasons for your choice', 30),
('Basic 5', 'History', 'history', 'Europeans in Ghana', 'International Trade Including the Slave Trade', 'B5.3.2.1', 'Understand that what began as trade in goods from 1471 soon included trade in humans by the 16thcentury', 'B5.3.2.1.1', 'Investigate why the Europeans began trading in humans by the 16th century. Enquiry Route: Which Europeans took part in the trade in humans? Why did the Europeans begin trading in humans?', '1. Use a map to explain the concept of Trans-Atlantic slave trade; 2. Role play/show documentary on how the slave trade was conducted.; 3. Brainstorm the reasons why the Europeans began trading in humans; 4. Visit/show pictures of some forts and castles; 5. In small groups learners develop a poster on the Trans- Atlantic Slave Trade; 6. Groups present their work to the whole class', 40),
('Basic 5', 'History', 'history', 'Colonisation and Developments under Colonial Rule in Ghana', 'Social Developments Under Colonial Rule', 'B5.4.2.1', 'Demonstrate understanding of the social developments that took place during the colonial period (1874-1957)', 'B5.4.2.1.1', 'Identify the developments in education during the colonial era (1874-1957). : Enquiry routes: Which schools were built during the colonial period? Where were they located? What did the British do to promote education?', '1. Identify schools that existed by 1930, where they are located and state some facts about these schools; 2. List some of the measures the British took to promote education in the Gold Coast. E.g. Ordinances to make sure all teachers were registered; 3. Discuss the role of the churches in Ghana’s education sector; 4. Recall the role of the important people in (a) the community and (b) the country who played key role in the educational sector. e.g. Dr Kwegyir Aggrey. NB: Display pictures of such people in the class.', 50),
('Basic 5', 'History', 'history', 'Colonisation and Developments under Colonial Rule in Ghana', 'Social Developments Under Colonial Rule', 'B5.4.2.1', 'Demonstrate understanding of the social developments that took place during the colonial period (1874-1957)', 'B5.4.2.1.2', 'Identify some of the health facilities and housing projects in the colonial period. Enquiry routes: What health facilities were built during the colonial period? How important were these social services?', '1. Discuss the health facilities and housing projects carried out during the colonial period e.g. the establishment of the Korle Bu hospital- 1923, Kumasi hospital, Takoradi hospital,; 2. Brainstorm the significance of these social services; 3. Show pictures/documentaries of these facilities to highlight the social facilities during the era', 60),
('Basic 5', 'History', 'history', 'Colonisation and Developments under Colonial Rule in Ghana', 'Economic Developments Under Colonial Rule', 'B5.4.3.2', 'Show understanding of the Economic policies and projects during the colonial period (1874- 1957)', 'B5.4.3.2.1', 'Describe the economic measures introduced during the colonial period including transport and communication projects. Enquiry routes: What were these economic development under colonial rule? How do sources of evidence help you to understand these developments under colonial rule?', '1. Identify the economic policies and projects during the colonial era.; 2. Enumerate contributions in the agricultural sector (e.g. setting up of agricultural station at Bunso, botanical garden at Aburi and Agricultural College at Kwadaso, promotion and marketing of cocoa farming), The construction of the Takoradi Harbour, construction of roads and railways and introduction of vehicles to link their main centres to evacuate and export items and facilitate movement.; 3. Discuss the role of Tetteh Quarshie in the introduction of cocoa into Ghana and how important cocoa has become.; 4. Visit/show pictures of any of these facilities e.g. Tetteh Quarshie farm.; 5. Enumerate contributions of the colonial government to mining sector.', 70),
('Basic 5', 'History', 'history', 'Journey to Independence', 'Early Protest Movements', 'B5.5.1.1', 'Show understanding of the factors that led to the formation of early protest movements in Ghana before1945', 'B5.5.1.1.1', 'Identify the early protest movements in Ghana before 1945. : Enquiry routes: what do we mean by early protest movements? What were some of these early protest movements? Who were the leaders of these early protest movements? What factors led to the formation of these movements', '1. What is a protest movement?; 2. List the main protest movements in Ghana before 1945: -Aborigines Rights Protection Society-ARPS- 1897 - National Congress of British West Africa-NCBWA- 1917 - The Gold Coast Youth Conference- 1929; 3. Discus the sequence of events that led to the formation of these movements (refer to subsequent indicators)', 80),
('Basic 5', 'History', 'history', 'Journey to Independence', 'Early Protest Movements', 'B5.5.1.1', 'Show understanding of the factors that led to the formation of early protest movements in Ghana before1945', 'B5.5.1.1.2', 'Examine sources of evidence about the role of Joseph Mensah Sarbah in the Aborigines Rights Protection Society-ARPS- 1897 : Enquiry routes: Who was Joseph Mensah-Sarbah? Where was he born? What was his role in the ARPS?', '1. Identify the key leaders of the ARPS by pictures/documentary; 2. Find out from the internet how the ARPS got the land bill withdrawn; 3. Present report as a poster', 90),
('Basic 5', 'History', 'history', 'Journey to Independence', 'Early Protest Movements', 'B5.5.1.1', 'Show understanding of the factors that led to the formation of early protest movements in Ghana before1945', 'B5.5.1.1.3', 'Examine sources of evidence about the role of Joseph Ephraim Casely-Hayford in the National Congress of British West Africa (NCBWA). Enquiry routes: Who was Joseph Ephraim Casely- Hayford? Where was he born? What was his role in the NCBWA?', '1. Identify Joseph Ephraim Casely-Hayford from photographs; 2. Show and discuss a documentary the bust of Joseph Ephraim Casely-Hayford at Casford Hall, UCC (where possible); 3. Present a narrative of the leadership role of Joseph Ephraim Casely-Hayford in the NCBWA; 4. Learners retell the story of Joseph Ephraim Casely-Hayford', 100),
('Basic 5', 'History', 'history', 'Journey to Independence', 'Early Protest Movements', 'B5.5.1.1', 'Show understanding of the factors that led to the formation of early protest movements in Ghana before1945', 'B5.5.1.1.4', 'Examine sources of evidence about the role of Dr Joseph Boakye Danquah in the Gold Coast Youth Conference Enquiry routes: Who was Joseph Boakye Danquah? Where was he born? What was his role in the Gold Coast Youth Conference?', '1. Present a narrative of the role of J.B. Danquah in the Gold Coast Youth Conference; 2. Field trip to Danquah Circle in Accra or his home where possible or show picture of Danquah Circle in Accra; 3. Learners retell the story of J.B. Danquah and the Gold Coast Youth Conference', 110),
('Basic 5', 'History', 'history', 'Journey to Independence', 'The 1948 Riots And After', 'B5.5.3.1', 'Show understanding of the sequence of events leading to the 1948 riots in Ghana', 'B5.5.3.1.1', 'Explain why people were unhappy in the country after the Second World War Enquiry routes: When was the Second World War fought? What promises were made to the Gold Coast soldiers who fought in the war? Why were people unhappy after the war?', '1. Show and discuss a documentary on the general state of affairs after the Second World War –failure to honour the promises to the ex-servicemen, lack of adequate housing and high cost of imported goods etc.; 2. Discuss how government handled their grievances at the time.; 3. Role play the scene for learners to offer the opinions on the situation (whether the riot was justified or not); 4. Guide learners to develop a poster that illustrates the link between the boycott of European goods, the shootings of 28th February and the riots of 1948', 120);
